(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-blip-2-bootstrapping-language-image-2023"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-1\">一 · 一个真实在线服务现场的崩塌点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-2\">二 · 旧方案的三条路线与各自的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-3\">三 · 模态鸿沟：为什么“直接拼”在数值上也不成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-4\">四 · 调度视角：两种负载的批处理特征不可通约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-5\">五 · 代价清单：延迟、吞吐、显存、带宽各欠一笔账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-6\">六 · 为什么“只训一个小模块”是系统级判断而非模型级妥协</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-7\">七 · 请求形态的三段分布：图像、前缀、文本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-8\">八 · 并发与批大小：两个池的批语义不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-9\">九 · SLO 分解：首 token、解码速率与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-10\">十 · 负载塑造方案：分辨率与查询数的反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-11\">十一 · 可核查的测量清单与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-12\">十二 · 从算子视角重看 Q-Former 的跨模态注意力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-13\">十三 · 数据类型分配：三段路径的敏感度并不相同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-14\">十四 · 累加精度与误差传播：softmax 与残差流是两条放大器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-15\">十五 · Blackwell 特性如何落到这三段 kernel 上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-16\">十六 · 一个具体例子：高分辨率单图请求的算子账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-17\">十七 · 精度与调度的耦合：分桶即精度分桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-18\">十八 · 桥接模块的精度边界：固定查询数下的数值预算与 Blackwell 算子代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-19\">十九 · 显存账本的三层结构：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-20\">二十 · KV cache：定长前缀是账本里最可控的一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-21\">二十一 · 分页、压缩、复用、卸载：四种手段各自的账本影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-22\">二十二 · 带宽瓶颈在哪：视觉侧是计算密集，语言侧是访存密集</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-23\">二十三 · HBM3e 容量怎么算：一个可复算的预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-24\">二十四 · 工程判断：把账本落到调度信号上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-25\">二十五 · 定长前缀下的显存账本与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-26\">二十六 · 定长前缀把调度问题切成两半</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-27\">二十七 · 连续批处理与前缀分桶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-28\">二十八 · chunked prefill 与软前缀的拼接时机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-29\">二十九 · 优先级、抢占与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-30\">三十 · 分离式预填/解码在 BLIP-2 路径上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-31\">三十一 · 分池调度下的尾延迟边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-32\">三十二 · 分池拓扑：三组件各自的并行维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-33\">三十三 · 集合通信的三种形态与何时压垮链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-35\">三十五 · NIXL 传输：跨池与跨节点的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-36\">三十六 · 通信成为瓶颈的判据与切分决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-37\">三十七 · 分池并行下的通信边界：切分维度与瓶颈判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-38\">三十八 · 精度塌陷：桥接模块是低比特下的第一道裂缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-39\">三十九 · OOM 的三条来源与分池隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-40\">四十 · 批抖动：视觉队列与解码队列的节拍不同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-41\">四十一 · 尾延迟：固定查询数掩盖不了长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-42\">四十二 · 静默降级与回滚：降级必须可观测、可逆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-43\">四十三 · 桥接模块的边界条件：查询数上限、队列积压与静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-44\">四十四 · 口径先行：BLIP-2 的基准表该长什么样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-45\">四十五 · 硬件档位与 batch：三段池的批形态根本不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-46\">四十六 · 并发与队列：尾延迟由视觉池排队主导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-47\">四十七 · 数字怎么读：哪些提升不可比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-48\">四十八 · 容量规划的机制推断：只能落到结构，不能落到数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-49\">四十九 · 迁移到别的模型：冻结假设先要成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-50\">五十 · 迁到别的领域：视觉侧假设最脆弱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-51\">五十一 · 哪里不适用：细粒度与长尾是硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-52\">五十二 · 规模上限：前缀复用率决定经济性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-53\">五十三 · 工程判断：迁移前先做三项核对</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-blip-2-bootstrapping-language-image-2023-sec-54\">五十四 · 迁移边界：定长前缀在什么条件下失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像预处理：图像缩放并切分为固定 patch 序列，送入冻结视觉编码器…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">查询聚合：Q-Former 以固定数量可学习查询向量对视觉特征做跨模态…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">模态投影：查询表示经线性层映射到语言模型隐层维度，作为软前缀拼接到文本…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前缀拼接与批调度：视觉前缀与文本 token 组成一条序列，按序列长度…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">自回归解码：冻结语言模型在视觉前缀与已生成 token 上做逐 tok…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后处理与返回：解码结果做文本后处理并按请求返回，视觉编码器侧特征可缓存…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-1\">一 · 一个真实在线服务现场的崩塌点</h3>\n<p>设想一个电商平台的商品图问答入口：用户上传一张商品图，附一句“这件外套有没有防水拉链”。请求进入网关后，图像被缩放到固定分辨率、切 patch，送入视觉编码器；文本 tokenizer 同步产出短 prompt；两者拼成一条序列交给语言模型自回归解码。峰值时段，这个入口的 QPS 由首页推荐位和促销活动共同驱动，图像分辨率分布极不均匀——主图是高清棚拍，买家秀是手机随手拍，长宽比从 1:1 到 9:16 都有。工程团队最初的做法是把视觉编码器和语言模型塞进同一个推理进程、同一张卡、同一次前向：视觉特征直接与文本嵌入拼接，端到端一次 forward 出结果。</p>\n<p>这套做法在离线评测里看不出问题，上线后尾延迟立刻失控。原因不在算力总量，而在两种负载的形态根本不兼容。视觉编码器的计算量随图像 patch 数线性增长，是典型的“大 batch、固定形状、计算密集”负载；语言模型的解码是逐 token 的自回归，KV cache 随序列增长，是“小步长、访存密集、对 batch 内序列长度极度敏感”的负载。把两者绑在同一次前向里，意味着一个 9:16 的高清买家秀会把同 batch 内所有短文本请求的解码步一起拖长，连续批处理（continuous batching）在视觉侧根本无法生效——视觉编码没有“逐 token”的概念，它是一次性吃完整个 patch 序列的。</p>\n<p>更致命的是显存。端到端拼接要求视觉特征序列原样驻留在语言模型的上下文里，序列长度等于 patch 数加上文本 token 数。一张高分辨率图的 patch 数可以轻易把上下文推到语言模型 KV cache 的容量边界，而 KV cache 是按 batch 内最长序列预分配的。结果是：一个高清请求进来，整条 batch 的 KV 预留被抬高，吞吐骤降，其余请求排队。工程上把这叫“长序列污染”，本质是视觉侧的分辨率自由度直接泄漏到了语言侧的显存预算里。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-2\">二 · 旧方案的三条路线与各自的代价</h3>\n<p>BLIP-2 之前，多模态推理栈的对齐做法大致收敛到三条路线，每条都在推理系统上留下不同的账单。</p>\n<ul>\n<li><b>端到端联合微调</b>：视觉编码器与语言模型一起训练、一起部署。对齐质量最好，但两侧大模型的参数都要参与反向传播，训练成本高；推理时两侧权重同池驻留，显存占用是两侧之和，且无法分别量化——视觉编码器对精度敏感、语言模型对权重量化更宽容，绑在一起就只能取最保守的精度档位。</li>\n<li><b>直接拼接 + 轻微微调</b>：冻结大部分参数，只训一个线性投影或 adapter。部署上看似轻，但视觉特征序列长度仍原样进入语言模型上下文，分辨率与序列长度没有解耦，KV cache 的容量压力一点没减。</li>\n<li><b>两阶段流水线但共享调度</b>：视觉编码与语言解码分成两个阶段，却共用同一个调度器和同一个 batch 队列。视觉阶段的长尾请求会阻塞语言阶段的批组装，连续批处理的收益被跨阶段的同步点吃掉。</li>\n</ul>\n<p>三条路线的共同痛点可以归结为一个公式层面的问题。设视觉编码器输出变长特征序列 $\\mathbf{V}\\in\\mathbb{R}^{N\\times d_v}$，$N$ 由图像 patch 数决定；语言模型隐层维度为 $d_l$。直接拼接要求把 $\\mathbf{V}$ 投影到 $d_l$ 后整段塞进上下文，于是语言模型侧的有效序列长度为</p>\n<div class=\"formula\">$$L_{\\text{ctx}} = N_{\\text{patch}} + L_{\\text{text}},\\qquad \\text{KV}_{\\text{bytes}} \\propto B \\cdot L_{\\text{ctx}} \\cdot d_l \\cdot \\text{layers}$$</div>\n<p>其中 $B$ 是 batch 大小。$N_{\\text{patch}}$ 随分辨率平方增长，而 $L_{\\text{ctx}}$ 又被 batch 内最长序列支配，于是分辨率分布的长尾直接转化为 KV 显存的乘性放大。这就是“非改不可”的量化理由：不是精度不够，是显存与调度的耦合让系统在真实请求分布下失去可预测性。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-3\">三 · 模态鸿沟：为什么“直接拼”在数值上也不成立</h3>\n<p>工程团队常把对齐问题当成一个工程胶水问题，以为加一层线性投影就完事。但冻结视觉编码器输出的特征空间与冻结语言模型的嵌入空间在维度和语义上都不匹配：视觉特征是逐 patch 的局部描述，语言模型消费的是离散 token 的分布式表示，两者之间没有共享的语义坐标。直接拼接后，语言模型看到的前缀是一段它从未在预训练中见过的分布外向量，注意力机制无法从中稳定提取信息，生成质量塌陷。</p>\n<p>要修这个鸿沟，旧路线只有两个选择：要么微调语言模型让它学会读视觉特征，要么微调视觉编码器让它输出语言模型能读的东西。两者都意味着动大模型参数——训练代价高，部署时还要把改动过的权重单独管理，量化策略被绑死。BLIP-2 的切入点正在这里：用一个轻量桥接模块承担对齐，两侧大模型保持冻结。桥接模块的参数量与显存占用远小于两侧，推理时只有它参与前向，于是对齐的代价被压缩到一个小模块上，视觉编码器与语言模型可以各自按自己的负载特征分池部署、分别量化、分别扩缩容。这条思路的具体机制（Q-Former 的查询聚合与两阶段预训练）属于本卷其他部分，此处只作为旧方案痛点的对照坐标。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-4\">四 · 调度视角：两种负载的批处理特征不可通约</h3>\n<p>把问题放到调度器层面看，旧方案的失败更清楚。视觉编码器的理想 batch 是大 batch、固定形状：一次前向吃进尽可能多的图像，GPU 利用率由矩阵乘的规模决定，batch 越大吞吐越高，单请求延迟对 batch 大小不敏感（只要不超出显存）。语言模型解码的理想 batch 则完全相反：连续批处理要求每个 decode step 都能动态加入新请求、移除已完成请求，batch 内序列长度参差，KV cache 按需分页。两者的最优 batch 策略在数学上不可通约——一个追求形状统一，一个追求长度异构。</p>\n<p>旧方案把两者塞进同一调度器，只能取折中：要么视觉侧牺牲 batch 规模去迁就语言侧的长度异构，GPU 利用率掉下来；要么语言侧按最长序列预分配 KV，短请求为长请求买单。真实请求分布下，图像分辨率的长尾比文本长度长尾更极端，折中的代价由尾延迟承担。工程上的可观测信号是：视觉编码队列深度先于解码队列上升，随后整条 batch 的 decode step 时间被拉长，P99 延迟出现阶跃。这个阶跃不是渐进劣化，是调度结构决定的硬拐点。</p>\n<p>另一个被低估的代价是前缀复用。同一张商品图会被多个用户在不同会话里反复提问，旧方案里每次请求都重新跑一遍视觉编码、重新占用一段 KV。若把视觉前缀缓存下来跨请求复用，理论上能省掉重复的视觉前向与重复的 KV 写入，但旧方案的端到端拼接让前缀与文本 token 在同一段 KV 里连续排布，缓存粒度无法切分——你没法只缓存视觉那段而不缓存文本那段。这要求前缀在 KV 布局上是一段可独立寻址的定长区域，而变长视觉特征序列做不到定长。定长前缀是解耦部署的前提，这一点在旧方案里是结构性缺失。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-5\">五 · 代价清单：延迟、吞吐、显存、带宽各欠一笔账</h3>\n<p>把旧方案的系统代价逐项拆开，可以看清为什么改造成本虽高却必须付。</p>\n<table class=\"mini\">\n<thead><tr><th>代价维度</th><th>旧方案的表现</th><th>根因</th></tr></thead>\n<tbody>\n<tr><td>尾延迟</td><td>P99 由 batch 内最长视觉序列支配，出现阶跃</td><td>视觉与解码共享 batch，长序列污染</td></tr>\n<tr><td>吞吐</td><td>视觉侧 batch 被迫缩小，GPU 利用率下降</td><td>两种负载最优 batch 策略不可通约</td></tr>\n<tr><td>显存</td><td>KV 按最长上下文预分配，分辨率长尾乘性放大</td><td>$L_{\\text{ctx}}$ 含 $N_{\\text{patch}}$，未解耦</td></tr>\n<tr><td>带宽</td><td>视觉特征整段写入 KV，重复请求重复写入</td><td>前缀无法定长、无法跨请求复用</td></tr>\n<tr><td>量化</td><td>两侧权重同池，只能取最保守精度档</td><td>无法按数值敏感度分别定精度</td></tr>\n</tbody>\n</table>\n<p>带宽这一项值得单独说。视觉特征序列的写入量与 $N_{\\text{patch}}\\cdot d_l$ 成正比，在 HBM 带宽成为解码瓶颈的场景下，这部分写入与解码的 KV 读写争抢同一份带宽预算。旧方案里视觉特征与文本 KV 混在同一段连续显存，缓存行利用率被变长布局打散，实际有效带宽低于理论值。若前缀是定长的，KV 布局可以按固定 stride 排布，缓存行对齐，复用时的读放大被压到最小——这是定长查询表示在系统层面的直接收益，不只是模型层面的压缩。</p>\n<p>功耗维度上，旧方案的端到端前向让视觉编码器在等待解码 batch 组装时保持活跃，GPU 时钟无法降档；分池部署后视觉池与语言池可以各自按队列深度做时钟与功率门控，空闲池可以真正 idle。这不是模型创新的直接目标，却是解耦部署在容量规划上的附带收益，也是工程团队在 SLO 与功耗预算之间做取舍时的实际杠杆。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-6\">六 · 为什么“只训一个小模块”是系统级判断而非模型级妥协</h3>\n<p>把对齐从大模型微调转移到轻量桥接，表面上是训练成本的节省，实质是推理系统边界的一次重划。旧方案里，视觉编码器与语言模型因为共享对齐参数而被绑成一个不可分割的部署单元：改一个精度档、换一个 batch 策略、扩一个池，都要动整个单元。桥接模块把对齐参数从两侧剥离后，部署单元变成三个可独立寻址的池——视觉池按图像 batch 扩缩容，桥接池按查询数固定形状做小 batch 前向，语言池按前缀长度与文本长度分桶做连续批处理。三个池的并发上限、排队超时、精度档位可以分别设定，容量规划从“整机预留”变成“按池预留”。</p>\n<p>这个重划的代价是桥接模块的聚合能力受固定查询数上限约束，细粒度视觉信息在聚合时可能丢失，高分辨率输入只增加视觉侧计算而不提升语言侧信息量——这是模型层面的已知局限，但在系统层面它换来的是语言模型序列长度与图像分辨率彻底解耦，KV 占用不再被分辨率长尾支配。对在线服务而言，可预测的尾延迟比无损的信息保留更值钱，因为 SLO 是按分位数签的，不是按平均质量签的。工程判断落在这里：当一个请求形态的分辨率分布无法收敛时，把分辨率自由度关在视觉池内部、不让它泄漏到语言池的 KV 预算里，是唯一能同时守住吞吐与尾延迟的结构性选择。BLIP-2 的定长查询表示正是这个判断的机制载体，后续的量化与调度优化都建立在这条解耦边界之上。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-7\">七 · 请求形态的三段分布：图像、前缀、文本</h3>\n<p>BLIP-2 推理路径上的请求不是一条均质序列，而是三段异质负载拼成的复合体：图像 patch 序列进入冻结视觉编码器，Q-Former 用固定查询数把它压成定长查询表示，投影后作为软前缀与用户文本 token 拼接，交给冻结语言模型自回归解码。三段负载的长度分布由不同变量决定：图像段长度随分辨率与 patch 切分变化，前缀段长度由查询数这一超参数钉死，文本段长度由用户输入与生成长度决定。工程上必须把这三段分开测量，否则任何“平均序列长度”都会掩盖真正的瓶颈。</p>\n<p>可核查的测量口径是：对每个请求记录 <em>(H, W, patch 数, 查询数, 前缀 token 数, 输入文本 token 数, 生成 token 数, 视觉编码耗时, 前缀拼接耗时, 首 token 时延, 解码总时延)</em>，并按前缀长度与文本长度做二维分桶直方图。前缀长度在 BLIP-2 中是常量，因此分桶实际只沿文本长度与图像分辨率两个轴展开；这意味着调度器的桶结构比纯文本 LLM 更简单，但也意味着前缀段的 KV 占用是一个不可压缩的固定底座。</p>\n<p>代价落在显存与带宽上：前缀定长意味着每个并发请求都携带一份固定大小的软前缀 KV，其字节数与前缀 token 数、层数、KV 头数与精度成正比。设前缀 token 数为 <span>L<sub>q</sub></span>，语言模型层数为 <span>N</span>，KV 头数为 <span>H<sub>kv</sub></span>，头维度为 <span>d</span>，每元素字节数为 <span>b</span>，则单请求前缀 KV 为：</p>\n<div class=\"formula\">$$M_{\\text{prefix}} = 2 \\cdot N \\cdot H_{kv} \\cdot d \\cdot L_q \\cdot b$$</div>\n<p>系数 2 来自 K 与 V 两份缓存。这个量对短文本请求而言占比极高：一个只生成十几个 token 的视觉问答请求，其 KV 主体是前缀而非生成部分。举例来说，若某请求输入文本仅二十余 token、生成十余 token，而前缀为固定查询数映射出的数十 token，则前缀 KV 占该请求 KV 总量的大头——这正是 BLIP-2 负载形态区别于纯文本服务的核心特征，也是分池部署与前缀复用机制存在的理由。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-8\">八 · 并发与批大小：两个池的批语义不同</h3>\n<p>视觉编码器池与语言模型池的批语义不可混为一谈。视觉池的批是“图像批”：批大小受图像分辨率决定的 patch 数与视觉编码器激活显存约束，批内每张图的 patch 数可以不同，但为效率通常按分辨率分桶后同批。语言池的批是“序列批”：批内每条序列由定长前缀加变长文本组成，连续批处理在解码步逐 token 增删序列，批大小随解码推进动态变化。把两个池的批大小设成同一个数是最常见的容量规划错误，因为二者的约束变量分别是视觉激活显存与 KV 显存。</p>\n<p>语言池的 KV 显存随并发线性增长，可写成：</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{batch}} = B \\cdot \\left( M_{\\text{prefix}} + M_{\\text{gen}} \\right),\\quad M_{\\text{gen}} = 2 N H_{kv} d \\, \\bar{L}_{\\text{gen}} \\, b$$</div>\n<p>其中 <span>B</span> 为并发批大小，<span>L̄<sub>gen</sub></span> 为平均已生成 token 数。由于 <span>M<sub>prefix</sub></span> 是常量，批大小上限在短文本场景下几乎完全由前缀决定；这解释了为什么在 BLIP-2 形态的服务里，提高并发的主要手段不是加长序列，而是前缀 KV 复用与分池扩缩容。</p>\n<p>具体机制上，调度器按“前缀长度 + 输入文本长度”分桶，同桶内做连续批处理，避免长文本请求与短文本请求互相拖累解码步节奏。一个可操作的伪代码思路是：请求到达后先查同图前缀缓存，命中则跳过视觉池直接进入语言池的“热前缀”队列；未命中则进入视觉池队列，按分辨率桶排队，编码完成后写入特征缓冲并生成前缀，再进入“冷前缀”队列。两条队列的 SLO 目标不同，热前缀请求的首 token 时延不含视觉编码，冷前缀请求则必须把视觉排队时间计入。</p>\n<p>吞吐代价体现在视觉池的空转：当语言池因 KV 显存满而限流时，视觉池若继续按图像批前向，会把已完成编码的前缀堆在特征缓冲里，占用显存却不产生解码吞吐。因此两个池的并发上限必须联动设置，视觉池的在途请求数应受语言池可用 KV 预算约束，否则队列深度监控会显示视觉侧“健康”而端到端尾延迟已经劣化。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-9\">九 · SLO 分解：首 token、解码速率与尾延迟</h3>\n<p>多模态请求的 SLO 不能只写一个端到端数字，必须拆成三段可独立归因的指标：视觉编码完成时延、首 token 时延（含前缀拼接与语言模型首步前向）、以及解码阶段的每 token 时延。三段中任何一段的尾部分布都可能主导整体 P99。可核查口径是分别对三段做分位数统计，并记录每段的排队时间与计算时间，使尾延迟能归因到“视觉队列积压”还是“解码步被长批拖慢”。</p>\n<p>尾延迟的主要来源在 BLIP-2 形态下是视觉编码队列积压，因为视觉池的扩缩容粒度粗、单张高分辨率图像的编码耗时远高于一次解码步。设视觉池服务率为 <span>μ<sub>v</sub></span>、到达率为 <span>λ<sub>v</sub></span>，则队列利用率 <span>ρ = λ<sub>v</sub>/μ<sub>v</sub></span>，等待时间随 <span>ρ→1</span> 非线性上升；而语言池的解码步是细粒度、可抢占式调度的，尾部相对平滑。因此容量规划应把视觉池的目标利用率压在明显低于语言池的水平，用更多副本换取尾延迟的稳定，而不是让两个池跑在同一利用率上。</p>\n<p>具体例子：一批同图多轮请求到达时，首轮请求走冷前缀路径，需排队等待视觉编码；后续轮次命中前缀缓存，直接进入热前缀队列。若调度器不区分两类请求的 SLO，冷前缀请求的排队会挤占热前缀请求的解码步预算，导致本应低时延的多轮追问被拖慢。正确做法是给热前缀队列预留解码批容量，冷前缀请求在视觉池侧单独限流，并在超时时按降级策略返回——降级可以是返回不含视觉上下文的文本回答，也可以是丢弃并让客户端重试，具体策略取决于业务对错误率的容忍度。</p>\n<p>功耗维度上，视觉池与语言池的能效曲线不同：视觉编码器是计算密集型前向，单位请求能耗随分辨率上升；语言解码是访存密集型逐 token 生成，单位 token 能耗随批大小与 KV 复用率改善。分池部署使两池可以独立选择功耗档位与时钟策略，但也意味着低负载时两池都难以进入深度休眠，因为任一侧的突发请求都会唤醒对应池。容量规划需把“最小副本数”作为功耗底线纳入考量。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-10\">十 · 负载塑造方案：分辨率与查询数的反向约束</h3>\n<p>负载形态不只被动影响方案，方案也反过来限制可接受的负载。BLIP-2 的固定查询数是一个硬约束：语言模型侧前缀长度与前缀 KV 不随图像分辨率变化，因此提高分辨率只增加视觉池计算与显存，不增加语言池负担。这给容量规划带来一个非对称的弹性：视觉池可以按分辨率分档扩缩容，语言池则按并发与文本长度扩缩容，两者解耦。但反向的限制同样明确——查询数上限决定细粒度信息保留程度，高分辨率输入不会自动转化为语言模型侧更多的视觉信息，因此“提高分辨率以提升质量”的请求在系统层面只买到视觉侧的计算开销，买不到前缀信息量的增长。</p>\n<p>这形成一条工程判断：若业务负载以高分辨率图像为主，视觉池会成为吞吐与尾延迟的主导，而语言池的 KV 预算相对宽松；此时优化重心应放在视觉编码的批效率与分辨率分桶上，而非语言侧。反之，若负载以短文本、低分辨率、高并发为主，语言池的前缀 KV 底座会成为并发上限的决定因素，优化重心转向前缀复用率与 KV 精度。测量口径上，应统计分辨率分布与同图重复率两个直方图，前者决定视觉池容量，后者决定前缀缓存命中率与热前缀队列占比。</p>\n<p>批大小对负载的反向塑造体现在分桶策略上：桶划分过细会导致批内序列长度方差小但批利用率低，桶划分过粗会让长短序列同批、解码步被最长序列拖慢。可核查的做法是记录每批的实际 token 利用率（有效 token 数除以批容量）与解码步时延的相关系数，用数据而非直觉选择桶边界。由于前缀定长，桶的方差主要来自文本段，这使得 BLIP-2 形态的分桶比纯文本服务更容易收敛到稳定配置。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-11\">十一 · 可核查的测量清单与失败模式</h3>\n<p>本卡不给出任何吞吐、时延与显存数字，材料未提供可核验的实测结果，因此容量结论只能落在机制层面。可核查的测量清单应包含以下条目，且每条都需带时间戳与请求标识以便归因：</p>\n<ul>\n<li>视觉池：队列深度、按分辨率桶的在途请求数、单图编码耗时分布、视觉激活显存峰值。</li>\n<li>前缀段：前缀 token 数（应为常量，用于校验配置一致性）、前缀 KV 字节数、前缀缓存命中率、冷/热前缀请求占比。</li>\n<li>语言池：批大小随解码步的变化曲线、每 token 时延分布、KV 显存占用与并发的关系、首 token 时延分段统计。</li>\n<li>端到端：按 SLO 分段的 P50/P99、超时降级触发次数、丢弃请求数与原因分类。</li>\n</ul>\n<p>失败模式有三类需要单独监控。其一是把固定查询数当作无损压缩：查询数上限决定细粒度信息保留程度，若业务侧持续提高分辨率而前缀信息量不变，质量投诉会以“看不清细节”的形式出现，而系统指标一切正常——这类失败只能靠离线质量评估发现，不能靠时延监控发现。其二是忽略视觉编码队列积压：视觉池与语言池扩缩容不同步时，尾延迟由视觉侧排队主导，若只监控语言池的解码时延，会误判系统健康。其三是在材料未给出量化与吞吐数字时引用具体指标：本卡的容量结论只能落到“前缀定长使语言池 KV 底座可预测”“分池部署使两池可独立扩缩容”这类机制判断上，任何具体并发数、显存占用与 P99 数值都不可引用。</p>\n<p>最后落到一个具体机制判断：BLIP-2 形态的负载治理核心是把“定长前缀”当作容量规划的不动点——语言池的 KV 预算按前缀常量加生成变量估算，视觉池的容量按分辨率分布与同图重复率估算，两池的并发上限通过前缀缓存的冷热分流联动。任何偏离这一不动点的调度策略，例如让视觉池与语言池共享同一并发上限，或让热前缀请求与冷前缀请求共用一条队列，都会在尾延迟上付出可测量的代价，而这一代价的归因只能靠上述分段测量口径完成。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-12\">十二 · 从算子视角重看 Q-Former 的跨模态注意力</h3>\n<p>BLIP-2 的推理路径在算子层面可以拆成三段互不相同的计算形态：视觉编码器侧的卷积/注意力混合前向、Q-Former 的跨模态注意力、语言模型侧的自回归解码。三者对 Tensor Core 的利用方式差异极大，这决定了精度分配不能一刀切。Q-Former 的核心运算是固定查询数 $N_q$ 对变长视觉特征序列 $\\mathbf{V}\\in\\mathbb{R}^{N_v\\times d_v}$ 做交叉注意力，其打分矩阵为</p>\n<div class=\"formula\">$$\\mathbf{A}=\\mathrm{softmax}\\!\\left(\\frac{\\mathbf{Q}\\mathbf{W}_Q\\,(\\mathbf{V}\\mathbf{W}_K)^{\\top}}{\\sqrt{d_k}}\\right),\\quad \\mathbf{z}=\\mathbf{A}\\,(\\mathbf{V}\\mathbf{W}_V)$$</div>\n<p>逐项解释：$\\mathbf{Q}\\in\\mathbb{R}^{N_q\\times d}$ 是可学习查询，$\\mathbf{W}_Q,\\mathbf{W}_K,\\mathbf{W}_V$ 是投影权重；$\\sqrt{d_k}$ 是缩放因子，防止点积随维度增长而饱和 softmax；$\\mathbf{A}$ 的形状是 $N_q\\times N_v$，注意这里 $N_q$ 固定而 $N_v$ 随图像分辨率线性增长。这意味着 Q-Former 的算力代价由 $N_q\\cdot N_v\\cdot d$ 主导，是典型的“小 M、大 N”GEMM——在 Blackwell 上这类形状对 2-SM MMA 的配对利用率不友好，因为 MMA 指令期望两个 SM 协同完成一个更大的 tile，而 $N_q$ 往往不足以填满 tile 的行方向。工程上的直接后果是：Q-Former 的 kernel 选择应以 wgmma/tcgen05 的 N 方向切分为主，把 $N_v$ 沿列方向分块，让每个 CTA 处理一段视觉特征，查询向量在 SMEM 中常驻复用。代价体现在延迟上：视觉编码队列的尾延迟往往不是被编码器本身主导，而是被这个 $N_q\\times N_v$ 打分矩阵在低利用率下的反复启动开销主导。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-13\">十三 · 数据类型分配：三段路径的敏感度并不相同</h3>\n<p>推理系统把视觉编码器、桥接模块、语言模型分池部署，精度也必须分池决策。视觉编码器输出的是逐 patch 的连续特征，后续要被 Q-Former 的 softmax 注意力消费，打分对特征动态范围敏感；Q-Former 的查询表示经线性投影成为软前缀，直接进入语言模型的残差流，是数值上最“贵”的一小段；语言模型解码则以权重为主、激活动态范围大。给定事实明确材料未给出量化方案，因此这里只给机制层面的分配原则，不给具体比特数结论。</p>\n<table class=\"mini\"><thead><tr><th>路径段</th><th>数值敏感点</th><th>精度取向</th><th>系统代价</th></tr></thead><tbody><tr><td>冻结视觉编码器</td><td>patch 特征动态范围、LayerNorm 统计</td><td>激活保持较高精度，权重可低比特</td><td>视觉池显存与带宽，分辨率提高时线性增长</td></tr><tr><td>Q-Former 交叉注意力</td><td>softmax 打分饱和、查询聚合的加性误差</td><td>打分与 softmax 用较高累加精度</td><td>算力小但延迟占比高，量化收益有限</td></tr><tr><td>投影层与软前缀</td><td>前缀直接进入残差流，误差被逐层放大</td><td>投影输出精度优先，权重可压</td><td>前缀 KV 显存，跨轮复用降低边际成本</td></tr><tr><td>冻结语言模型</td><td>KV cache 动态范围、注意力 logits</td><td>权重低比特、KV 单独定精度</td><td>解码吞吐与 KV 带宽是主成本</td></tr></tbody></table>\n<p>关键判断是：软前缀只有固定长度，它的量化误差不会因为图像分辨率提高而摊薄，反而在长上下文解码中被反复读取。因此投影层输出的前缀应当被视为“高价值小张量”，在 FP8 与更高精度之间优先保精度，而把低比特预算留给语言模型权重与 KV cache——后者体量大、复用次数多，低比特带来的带宽节省能直接换成吞吐。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-14\">十四 · 累加精度与误差传播：softmax 与残差流是两条放大器</h3>\n<p>低精度 GEMM 的误差并不等价地进入最终 logits。Q-Former 路径上有两个放大器。第一是 softmax：打分矩阵 $\\mathbf{A}$ 的微小扰动经指数归一化后会被非线性放大，尤其在 $N_v$ 较大、注意力分布接近均匀时，低精度累加会让归一化分母产生系统性偏移，表现为查询表示整体幅度漂移。第二是残差流：软前缀作为序列最前面的 token 参与每一层注意力，其误差在 $L$ 层中近似按残差路径累积，可用一阶模型估计</p>\n<div class=\"formula\">$$\\epsilon_{\\text{out}}\\approx\\epsilon_{\\text{prefix}}+\\sum_{l=1}^{L}\\left\\|\\mathbf{W}_l\\right\\|\\,\\epsilon_{l}$$</div>\n<p>逐项解释：$\\epsilon_{\\text{prefix}}$ 是投影层输出的量化误差，$\\mathbf{W}_l$ 是第 $l$ 层残差分支的有效增益，$\\epsilon_l$ 是该层内部累加误差。这个式子说明前缀误差是“常数项”，不随层数衰减；而层内误差是“累加项”，随深度增长。工程含义是：把前缀做高精度、把层内 GEMM 做低比特，比反过来更划算。累加精度的具体做法上，FP8 GEMM 的乘加通常在更高位宽累加器中完成，NVFP4 的块缩放又把动态范围压缩到块内共享指数，块大小与缩放因子精度直接决定前缀误差的量级。代价体现在显存与带宽：KV cache 若按低比特存储，前缀部分的读取带宽下降，但前缀复用意味着这部分节省只在热前缀请求上兑现，冷前缀首轮仍要付出写入成本。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-15\">十五 · Blackwell 特性如何落到这三段 kernel 上</h3>\n<p>tcgen05 是 Blackwell 第五代 Tensor Core 的指令族，其核心变化是把 MMA 的累加器从寄存器文件搬到 TMEM（Tensor Memory）。对 BLIP-2 的推理路径，这带来两个具体影响。其一是 Q-Former 的打分矩阵：$N_q$ 很小，寄存器累加器在传统 wgmma 下会因 tile 形状不匹配而浪费，而 tcgen05 允许把累加结果驻留在 TMEM 中，配合异步 MMA 与后续 softmax 的流水，减少寄存器压力与同步开销。其二是语言模型解码的 GEMM：自回归解码是典型的“瘦长”矩阵乘，M 方向只有 batch×1，tcgen05 的异步特性让权重加载与 MMA 重叠，TMEM 作为累加缓冲避免了每步的寄存器溢出。</p>\n<p>2-SM MMA 指的是两个 SM 协同执行一条 MMA 指令，共享更大的 tile。它对 Q-Former 的意义是双面的：$N_v$ 方向可以跨 SM 切分，提高大分辨率输入的利用率；但 $N_q$ 固定且通常较小，配对的两个 SM 在行方向上仍可能欠载，调度器需要把多个请求的 Q-Former 前向拼成一批来填满 tile，这与“按前缀长度分桶”的批调度策略直接耦合。代价是显存：TMEM 是有限资源，每个 CTA 占用的 TMEM 列数决定了同 SM 上可并发的 CTA 数量，Q-Former 与语言模型若混布在同一 SM 上会互相挤占；分池部署在这里不只是调度选择，也是 TMEM 资源的隔离手段。功耗侧，第五代 Tensor Core 在低利用率下并不会按比例省电，欠载的 MMA 仍消耗时钟，因此把 Q-Former 的小 GEMM 合并成批是能效上的必要动作，而非可选优化。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-16\">十六 · 一个具体例子：高分辨率单图请求的算子账</h3>\n<p>设一张高分辨率图像被切成更多 patch，视觉特征序列长度 $N_v$ 随之增大，而查询数 $N_q$ 固定。视觉编码器侧的计算随 $N_v$ 线性增长，这是视觉池的排队来源；Q-Former 的打分矩阵从 $N_q\\times N_v$ 变大，算力仍小但 kernel 启动与 TMEM 占用上升；投影后的软前缀长度不变，语言模型侧的序列长度、KV 占用与解码步数完全不受分辨率影响。这个解耦正是 BLIP-2 在推理系统上的核心价值：分辨率只买视觉侧算力，不买语言侧延迟。</p>\n<p>但算子层面有一个陷阱：把固定查询数当作无损压缩。查询数上限决定细粒度信息保留程度，高分辨率输入不会自动提升语言模型侧信息量——多出来的 $N_v$ 只让 softmax 的分母更大、注意力分布更平，若查询表示的低比特量化误差同时存在，聚合结果的信噪比反而下降。工程判断是：当分辨率提升而查询数不变时，应优先保 Q-Former 打分与 softmax 的累加精度，而不是把省下的精度预算全给语言模型；同时监控视觉编码队列深度，因为此时尾延迟由视觉池排队主导，而非解码。若视觉池与语言池扩缩容不同步，前缀拼接前的等待会吞掉分辨率带来的任何收益。</p>\n<p>KV 侧的账同样具体：软前缀与已生成 token 是唯一被缓存的部分，同图多轮请求复用前缀 KV，首轮冷前缀要付出写入与首次读取成本，后续热前缀只付读取。低比特 KV 的收益在热前缀上兑现得更充分，因为复用次数摊薄了量化/反量化的固定开销；冷前缀首轮则应避免在写入路径上做额外转换，把精度转换放在读取侧。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-17\">十七 · 精度与调度的耦合：分桶即精度分桶</h3>\n<p>连续批处理按前缀长度与文本长度分桶，这个分桶在数值上也有含义：同一桶内的序列前缀长度相同，意味着 KV cache 的量化块边界对齐，块缩放因子可以按桶共享，减少每步解码的缩放因子加载开销。反过来，若把长短前缀混在同一批里，KV 的低比特块缩放会退化为逐序列处理，带宽收益被抵消。因此调度器的分桶策略与量化方案必须联合设计，而不是先定量化再定调度。</p>\n<p>失败模式在算子层面表现为两类：一是欠载的 MMA 在低查询数下反复启动，延迟被 kernel launch 与 TMEM 分配主导，此时增加 batch 比提高精度更有效；二是前缀量化误差在长解码中被逐层放大，表现为生成文本的语义漂移而非崩溃，监控上应跟踪前缀表示的幅度统计与首 token 分布偏移，而不是只看吞吐。材料未给出量化方案与吞吐时延数字，因此上述判断只能落在机制层面：精度分配按路径段敏感度、累加精度优先保 softmax 与前缀、低比特预算给权重与 KV、分桶与量化块对齐——这四条是可执行的工程约束，具体比特数与收益需在目标负载上实测后才能定档。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-18\">十八 · 桥接模块的精度边界：固定查询数下的数值预算与 Blackwell 算子代价</h3>\n<p>BLIP-2 推理路径里真正进入 Tensor Core 的只有两段：冻结视觉编码器的 patch 卷积与注意力，以及 Q-Former 的跨模态注意力与投影。查询数固定意味着 Q-Former 的注意力矩阵形状是 <span>Q×N</span>（Q 为查询数，N 为视觉 patch 数），N 随分辨率增长而 Q 不变，于是跨模态注意力的算术强度随分辨率上升而下降——高分图像下这段 kernel 从计算受限滑向带宽受限。Blackwell 上应把 Q-Former 的跨模态注意力交给 tcgen05 MMA，让 Q 维落在 TMEM 的累加器上、N 维沿 K 方向分块流式读入视觉特征，避免把整条 patch 序列常驻寄存器；2-SM MMA 只在 Q 与输出投影维度足够大时才值得启用，查询数偏小时双 SM 协同的同步开销会吃掉收益。代价落在视觉池：分辨率翻倍使视觉编码器前向与特征缓冲写入近似线性增长，而语言模型侧前缀长度与 KV 占用不变，容量规划必须把显存与带宽预算记在视觉池账上，不能按语言池的定长前缀推算。</p>\n<div class=\"formula\">$$\\mathbf{z}=\\mathrm{QFormer}(\\mathbf{V}),\\quad \\mathbf{h}=\\mathbf{W}\\mathbf{z},\\quad \\hat{y}_t=\\arg\\max\\;p(y_t\\mid \\mathbf{h},y_{&lt;t})$$</div>\n<p>逐项看：<span>V</span> 是逐 patch 视觉特征，精度由冻结视觉编码器决定，通常 FP16/BF16；Q-Former 内部跨模态注意力的 QK^T 与 softmax 需要更高累加精度，FP8 下 QK^T 的指数项对视觉特征动态范围敏感，NVFP4 的块缩放虽能压住离群值，但查询向量是少量可学习参数、其分布窄，低比特量化误差会直接改变聚合权重而非仅扰动输出，因此桥接模块的低比特收益必须用端到端生成质量验证，不能只看单层误差；<span>W</span> 投影把定长查询映射到语言模型隐层，这一层是唯一跨两侧精度域的接口，投影权重宜保持与语言模型输入嵌入一致的精度以避免前缀分布漂移；最后一项解码完全在冻结语言模型内，其 KV cache 只覆盖软前缀与已生成 token，前缀 KV 可在同图多轮请求间复用，但复用的前提是投影输出逐位一致，若桥接模块按请求动态量化，热前缀缓存就会失效。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>精度取向</th><th>系统代价</th></tr></thead><tbody><tr><td>视觉编码器</td><td>FP16/BF16，按敏感度定</td><td>分辨率线性抬升算力与特征缓冲带宽</td></tr><tr><td>Q-Former 跨模态注意力</td><td>FP8 需验证 softmax 动态范围</td><td>N 增长使算术强度下降，转向带宽受限</td></tr><tr><td>投影层</td><td>与语言模型输入嵌入同域</td><td>精度漂移即破坏前缀 KV 复用</td></tr><tr><td>语言模型解码</td><td>冻结权重，前缀定长</td><td>KV 仅覆盖前缀与已生成 token</td></tr></tbody></table>\n<p>失效条件集中在两处。其一是把固定查询数当成无损压缩：查询数上限决定聚合后保留的细粒度信息量，提高分辨率只增加视觉侧计算与跨模态注意力的 N 维，不会自动提升语言模型侧信息量，于是高分辨率输入在视觉池付出带宽代价却在语言侧拿不到对应收益，这是分辨率与查询数不匹配时的典型浪费。其二是视觉池与语言池扩缩容不同步：视觉编码队列积压时请求在前缀拼接前等待，尾延迟由视觉侧排队主导，而语言池因前缀定长、批形状稳定反而空闲，此时按语言池利用率做容量判断会系统性低估视觉侧压力。数值上还有一条硬边界——材料未给出量化方案与精度分配的可核验数字，桥接模块与投影层在 FP8/NVFP4 下的数值稳定性、视觉编码器与语言模型的精度取舍均无实测结论，因此任何“低比特桥接不掉点”的判断都只能落到机制推断：查询向量参数少、分布窄，低比特误差经 softmax 放大后进入前缀，再由自回归解码逐 token 累积，这条链路的敏感度高于纯视觉分类任务。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-19\">十九 · 显存账本的三层结构：权重、激活、KV</h3>\n<p>在 BLIP-2 的推理路径上，显存不是一块整账，而是三块性质完全不同的账：冻结权重、前向激活、以及自回归解码的 KV cache。三者对容量的压力方式不同，工程上必须分开算。冻结权重是静态的、按池归属的：视觉编码器池、桥接池、语言模型池各自持有一份，互不共享；激活是瞬态的、按批内最长序列与最大分辨率决定的；KV cache 是随解码步数线性增长的、按并发请求数放大的。把三者混在一个“总显存”里做规划，是容量估算失准的首要原因。</p>\n<p>设视觉编码器权重 <span>W_v</span>、桥接模块权重 <span>W_q</span>（含 Q-Former 与线性投影）、语言模型权重 <span>W_l</span>，每张卡上的静态占用为</p>\n<div class=\"formula\">$$M_{\\text{static}} = \\frac{W_v}{N_v} + \\frac{W_q}{N_q} + \\frac{W_l}{N_l} + M_{\\text{runtime}}$$</div>\n<p>其中 <span>N_v, N_q, N_l</span> 是三个池各自的并行度，<span>\\(M_{\\text{runtime}}\\)</span> 是 CUDA context、通信缓冲、NCCL/NIXL 注册内存等不可压缩的常驻开销。注意 <span>N_q</span> 通常远小于 <span>N_v</span> 与 <span>N_l</span>——桥接模块参数量小，可以整块放在少量卡上，甚至与语言模型池共卡，这是 BLIP-2 解耦部署带来的直接显存红利：桥接部分不随两侧大模型一起复制。</p>\n<p>一个具体例子：假设视觉编码器池 4 卡、语言模型池 8 卡、桥接池 1 卡。若把桥接塞进语言模型池，则 8 卡各持一份桥接权重；单独成池则只需 1 份。桥接权重虽小，但在多副本部署下这份差异会随副本数线性放大。工程判断是：桥接池独立成池、按前缀长度分桶后的并发量单独扩缩，比把它绑在语言模型池上更省显存，也更利于按请求形态做容量规划。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-20\">二十 · KV cache：定长前缀是账本里最可控的一项</h3>\n<p>BLIP-2 的 KV 结构有一个别的多模态路径少有的性质：软前缀长度由查询数固定，与图像分辨率无关。设查询数为 <span>Q</span>，用户文本 token 数为 <span>T</span>，已生成 token 数为 <span>G</span>，语言模型层数为 <span>L</span>，隐层维度为 <span>d</span>，每层 KV 头数为 <span>H_{kv}</span>，每头维度为 <span>d_h</span>，每元素字节数为 <span>b</span>，则单请求 KV 占用为</p>\n<div class=\"formula\">$$M_{\\text{KV}} = 2 \\cdot L \\cdot H_{kv} \\cdot d_h \\cdot b \\cdot (Q + T + G)$$</div>\n<p>系数 2 来自 K 与 V 两份。这个式子里只有 <span>G</span> 是随解码增长的变量，<span>Q</span> 是常量，<span>T</span> 由请求形态决定。把分辨率从 224 提到 448，视觉编码器侧 patch 数翻数倍、激活与计算量随之上升，但上式中的 <span>Q</span> 不变——语言模型侧的 KV 账本对分辨率完全不敏感。这是容量规划里最值得利用的一条：视觉侧的扩容是计算扩容，语言侧的扩容才是 KV 扩容，两者不该用同一个扩缩容信号驱动。</p>\n<p>代价面在于 <span>Q</span> 的固定性是一把双刃剑。查询数上限决定细粒度信息保留程度，高分辨率输入不会自动提升语言模型侧信息量；换言之，KV 账本被压得很稳，但这份“稳”是以信息带宽为代价换来的。工程上不能把定长前缀当作无损压缩来规划容量，否则会在高分辨率、细粒度问答场景下出现“显存够、信息不够”的错配。</p>\n<p>具体例子：同图多轮请求下，首轮冷前缀需要完整前向并写入 KV，后续轮次可直接复用前缀 KV，只增量计算新增文本与生成部分。此时单请求 KV 账本从 <span>Q+T_1+G_1</span> 变为 <span>Q+T_2+G_2</span> 的增量部分，前缀段是共享的。SLO 必须把首轮冷前缀与后续热前缀分开设目标，否则尾延迟统计会被冷启动请求污染。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-21\">二十一 · 分页、压缩、复用、卸载：四种手段各自的账本影响</h3>\n<p>分页（paged KV）把 KV 按固定大小的 block 管理，消除连续分配造成的碎片，使 <span>Q+T+G</span> 这种变长序列能以块为单位拼装。对 BLIP-2 而言，分页的直接收益是前缀段可以被多个请求的 block table 指向同一物理块——这正是同图多轮复用的实现基础。代价是块表查询带来的间接寻址开销，以及块粒度与桶调度粒度不匹配时的内部浪费。</p>\n<p>压缩有两条路：量化 KV（降低 <span>b</span>）与减少 <span>Q</span> 或 <span>T</span> 的有效长度。前者直接按比例缩小上式，后者改变账本结构。BLIP-2 的查询数固定意味着 <span>Q</span> 这一项在部署档位确定后就不可调，压缩只能落在 <span>b</span> 与 <span>T</span> 上。材料未给出量化方案，桥接模块与投影层在低比特下的数值稳定性、视觉编码器与语言模型的精度分配均无数字，因此 KV 量化的收益只能定性表述为“按字节比例缩减”，不能引用具体倍数。</p>\n<p>复用是 BLIP-2 账本里性价比最高的一项：前缀 KV 在同一图像的多轮请求间共享，物理块只存一份，逻辑上被多个请求引用。复用率取决于同图请求的聚集程度，工程上应把同图请求尽量路由到同一语言模型副本，否则复用退化为跨卡重复存储。</p>\n<p>卸载（offload）把冷前缀或长历史 KV 换出到主机内存或远端存储。代价是 PCIe 或网络往返带宽，对解码步的尾延迟是硬伤。BLIP-2 场景下更合理的卸载对象是“已结束但可能被再次问及”的图像前缀，而不是活跃解码中的 KV。具体例子：一个图像被连续追问五轮后进入静默，其前缀 KV 可整体换出；若第六轮再来，换入代价是一次前缀长度的带宽传输，而不是重新跑视觉编码器——后者代价高得多。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-22\">二十二 · 带宽瓶颈在哪：视觉侧是计算密集，语言侧是访存密集</h3>\n<p>两侧的瓶颈性质不同，这是分池部署的物理依据。视觉编码器处理 patch 序列，是典型的高算术强度前向：权重读入一次、激活在片上反复使用，瓶颈偏向算力与片上容量。语言模型的自回归解码每步只处理一个 token，权重要被完整读一遍而只做一次乘加，算术强度极低，瓶颈是 HBM 带宽。BLIP-2 把两者拆开，等于把“算力受限”和“带宽受限”两类负载放到不同的卡、不同的扩缩容信号上，避免一类负载的瓶颈拖累另一类。</p>\n<p>解码步的理论下限由权重字节数与 HBM 带宽决定。设语言模型权重字节数为 <span>B_l</span>，有效带宽为 <span>BW</span>，则单步解码的时间下限近似为</p>\n<div class=\"formula\">$$t_{\\text{step}} \\gtrsim \\frac{B_l}{BW \\cdot \\eta}$$</div>\n<p>其中 <span>\\(\\eta\\)</span> 是带宽利用率。这个式子说明：解码吞吐的上限由“每步搬多少权重”决定，连续批处理通过让多个请求共享同一次权重搬运来摊薄这项成本，因此批大小是解码侧最有效的吞吐杠杆。反过来，KV 读取量随批内总 token 数增长，当批大到 KV 读取开始与权重读取争抢带宽时，吞吐曲线出现拐点——这个拐点就是该副本的最优批大小，需按前缀长度分布实测确定，材料未给出具体数值。</p>\n<p>具体例子：视觉池的批由图像数与分辨率决定，语言池的批由前缀长度与文本长度分桶决定。若把两侧混在同一张卡上，视觉前向的大激活会挤占语言解码的 KV 空间与带宽，尾延迟由视觉侧排队主导。工程判断是：视觉编码队列深度必须单独监控，视觉池与语言池的并发上限分别设置，扩缩容不同步时尾延迟会由视觉侧积压决定。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-23\">二十三 · HBM3e 容量怎么算：一个可复算的预算</h3>\n<p>容量规划的正确顺序是：先扣常驻，再扣权重，再按目标并发反推 KV 预算，最后检查激活峰值是否放得下。设单卡 HBM 容量为 <span>C</span>，则可用于 KV 与激活的空间为</p>\n<div class=\"formula\">$$C_{\\text{avail}} = C - M_{\\text{runtime}} - \\frac{W_v}{N_v} - \\frac{W_q}{N_q} - \\frac{W_l}{N_l}$$</div>\n<p>再设目标并发请求数为 <span>\\(N_{\\text{req}}\\)</span>，平均前缀加文本长度为 <span>\\(S_{\\text{in}}\\)</span>，平均生成长度为 <span>\\(S_{\\text{out}}\\)</span>，则 KV 需求为</p>\n<div class=\"formula\">$$M_{\\text{KV,total}} = N_{\\text{req}} \\cdot 2 L H_{kv} d_h b \\cdot (S_{\\text{in}} + S_{\\text{out}})$$</div>\n<p>可支撑并发为 <span>\\(N_{\\text{req}} \\le (C_{\\text{avail}} - M_{\\text{act,peak}}) / M_{\\text{KV,per-req}}\\)</span>，其中 <span>\\(M_{\\text{act,peak}}\\)</span> 是批内最长序列与最大分辨率下的激活峰值。这个不等式是容量规划的核心：它把“卡有多大”翻译成“能同时服务多少个请求”，而 <span>\\(S_{\\text{in}}\\)</span> 中的 <span>Q</span> 是常量、<span>T</span> 是分布量，因此并发上限对文本长度分布敏感、对图像分辨率不敏感。</p>\n<p>可复算的例子（仅演示结构，不引用实测数字）：取 <span>L</span>、<span>H_{kv}</span>、<span>d_h</span>、<span>b</span> 为部署档位给定值，<span>Q</span> 为查询数固定值，若 <span>\\(S_{\\text{in}}\\)</span> 从短文本分布切换到长文本分布，<span>\\(M_{\\text{KV,per-req}}\\)</span> 线性上升，可支撑并发线性下降。工程上应把 <span>T</span> 的分布按分桶统计，用分桶后的加权平均而非全局平均做预算，否则长短序列混批会让实际并发低于账面值。分页与块粒度决定了这个加权平均的实现精度：块越大，短序列的内部浪费越多。</p>\n<p>激活峰值这一项在多模态路径上容易被低估：视觉编码器的激活与 patch 数成正比，分辨率提高只增加视觉侧计算与激活，不改变语言模型前缀长度与 KV 占用。因此视觉池的容量规划应按最大分辨率算激活峰值，语言池按前缀定长与文本分布算 KV，两者用不同的预算表，不能合并成一张。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-24\">二十四 · 工程判断：把账本落到调度信号上</h3>\n<p>账本算出来不是为了写在文档里，而是为了变成调度器的准入信号。BLIP-2 的分池结构给出三个可独立观测的量：视觉编码队列深度、前缀长度分布、解码尾延迟。容量规划应把这三个量映射到三个独立的扩缩容阈值，而不是用一个 GPU 利用率指标统管。视觉队列积压时扩视觉池，前缀长度分布右移时扩语言池并调整分桶边界，解码尾延迟超 SLO 时优先检查 KV 带宽争抢与批大小拐点。</p>\n<p>具体机制上，准入控制应按 <span>\\(M_{\\text{KV,per-req}}\\)</span> 而非请求数计费：一个长文本请求占用的 KV 可能是短文本请求的数倍，按请求数限流会让长文本请求把 KV 预算吃穿。同图多轮请求应带上前缀复用标记，调度器据此把 <span>Q</span> 段计为共享块、只对新增加部分计费，这样热前缀请求的准入成本显著低于冷前缀请求，SLO 也能分层设定。</p>\n<p>最后落在一条工程判断上：BLIP-2 的显存账本之所以可控，根源是查询数固定使 <span>Q</span> 从变量变成常量，从而把语言模型侧的 KV 预算从“随分辨率漂移”变成“随文本分布漂移”。容量规划应围绕这个常量做文章——把 <span>Q</span> 段做成可共享、可分页、可卸载的稳定块，把 <span>T</span> 与 <span>G</span> 段做成按分布计费的浮动块，两侧池用各自的预算表与扩缩容信号，而不是把整条多模态路径塞进一张卡的同一个显存池里。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-25\">二十五 · 定长前缀下的显存账本与失效边界</h3>\n<p>BLIP-2 的显存结构之所以可算，是因为语言模型侧的序列长度被查询数钉死：视觉编码器输出逐 patch 特征，Q-Former 以固定数量查询向量做跨模态注意力，得到定长查询表示，再经线性投影拼成软前缀。于是前缀长度 <em>L</em><sub>p</sub> 与图像分辨率解耦，KV 账本只随 <em>L</em><sub>p</sub>、已生成 token 数 <em>L</em><sub>g</sub>、层数 <em>N</em><sub>L</sub>、KV 头数 <em>H</em><sub>kv</sub>、头维 <em>d</em>、每元素字节 <em>b</em> 与并发序列数 <em>B</em> 变化：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} = B \\cdot N_L \\cdot H_{kv} \\cdot d \\cdot (L_p + L_g) \\cdot 2 \\cdot b$$</div>\n<p>系数 2 对应 K 与 V 两份。把 <em>L</em><sub>p</sub> 固定住，等于把 KV 的“冷启动税”变成常数项，容量规划可以按桶做：短文本桶与长文本桶的差异只落在 <em>L</em><sub>g</sub> 上。代价是前缀本身仍占一份不可压缩的显存，且同图多轮请求复用前缀 KV 时，这份前缀在缓存里被钉住，热前缀命中率越高、常驻前缀副本越多，可分配给解码的剩余 KV 块越少。分页与压缩只能在这条式子上做乘法项削减，不能改变定长前缀这一结构性事实。</p>\n<p>带宽瓶颈的位置由两池的算术强度决定。视觉编码器侧是逐 patch 的大矩阵乘，权重读取占主导，分辨率提高只增加该侧计算与激活，不改变语言侧序列长度；语言解码侧则是逐 token 自回归，每步要把全部 KV 读一遍，属于典型的带宽受限。因此把视觉池与语言池混部会互相污染：视觉池的长前向拉高 SM 占用与功耗，语言池的尾延迟被拖长。分池部署、分别量化、按前缀长度分桶做连续批处理是唯一能把两侧瓶颈解耦的调度形态；桥接模块与投影层参数量远小于两侧大模型，可优先低比特，但其在低比特下的数值稳定性材料未给出可核验结论，不能据此宣称精度分配已定。</p>\n<p>失效条件集中在三处。其一，把固定查询数当作无损压缩：查询数上限决定细粒度信息保留程度，高分辨率输入只增加视觉侧计算而不提升语言侧信息量，桥接聚合能力先饱和。其二，视觉编码队列积压：两池扩缩容不同步时，尾延迟由视觉侧排队主导，请求在前缀拼接前等待，必须为视觉池单独设并发上限与排队超时，并按 SLO 降级返回。其三，首轮冷前缀与后续热前缀的时延目标混为一谈，会把缓存命中率误当吞吐能力。可复算的预算只能落到机制层面：给定 <em>L</em><sub>p</sub>、<em>L</em><sub>g</sub> 与 <em>B</em> 即可按上式估 KV 上限，再叠加两侧冻结权重的常驻占用与视觉特征缓冲，剩余空间才是可调度余量；材料未给出量化方案与实测吞吐，任何具体容量数字都不应写入容量规划。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-26\">二十六 · 定长前缀把调度问题切成两半</h3>\n<p>BLIP-2 的推理路径给调度器留下了一个非常具体的结构：视觉编码器输出逐 patch 的变长特征序列，Q-Former 用固定数量查询向量做跨模态注意力，输出定长查询表示，线性投影后作为软前缀拼到文本 token 之前。这意味着语言模型侧的序列长度只由「查询数 + 文本长度」决定，与图像分辨率无关。调度器因此可以把一条请求拆成两个性质完全不同的阶段：视觉编码阶段，计算量随分辨率增长、输出长度恒定；语言解码阶段，前缀长度恒定、生成长度随请求变化。</p>\n<p>把这两个阶段放进同一个批里是低效的。视觉编码器是计算密集的卷积/注意力前向，批内不同分辨率的图像需要 padding 或分桶；语言模型是自回归解码，批内不同前缀长度和生成长度会造成严重的负载不均。BLIP-2 的机制原型允许二者分池部署：视觉池按图像批做数据并行，语言池按序列长度分桶做连续批处理。代价是跨池的数据搬运——视觉特征缓冲到 Q-Former 再到语言模型输入，这条路径上的显存带宽与同步开销必须计入端到端延迟，而不能只统计两侧各自的 kernel 时间。</p>\n<div class=\"formula\">$$L_{\\text{e2e}} = L_{\\text{vis}} + L_{\\text{bridge}} + L_{\\text{queue}}^{\\text{vis}} + L_{\\text{prefill}} + L_{\\text{decode}}$$</div>\n<p>举例：一张高分辨率图进入视觉池，patch 序列变长使 $L_{\\text{vis}}$ 上升，但 Q-Former 输出的查询数不变，因此 $L_{\\text{prefill}}$ 与 KV 占用不随分辨率变化。调度器若把视觉池与语言池的并发上限设为同一数值，高分辨率请求会先在视觉侧排队，尾延迟由 $L_{\\text{queue}}^{\\text{vis}}$ 主导——这正是分池部署下最典型的失配。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-27\">二十七 · 连续批处理与前缀分桶</h3>\n<p>语言池的连续批处理（continuous batching）在解码每一步动态重组批：完成的序列退出，新到达的序列插入。BLIP-2 的前缀定长特性让这件事比通用文本模型更简单——所有请求的软前缀长度相同（查询数固定），差异只来自文本长度与已生成长度。调度器可以按「前缀 + 文本」的总长度分桶，把长度接近的请求放进同一批，避免短请求被长请求拖住。</p>\n<p>伪代码思路：维护一个按总长度排序的等待队列，每步解码后回收已完成的 slot，从队列头部取长度最接近当前批平均值的请求填入。由于前缀部分对所有请求等长，分桶的方差主要来自文本侧，桶的数量可以很少。代价是显存：每个活跃序列都要占一份前缀 KV，前缀定长意味着这部分占用可预测，容量规划可以按「最大并发数 × 前缀 KV 大小」直接估算，而不必为分辨率留余量。</p>\n<table class=\"mini\"><thead><tr><th>调度对象</th><th>长度决定因素</th><th>批内方差来源</th><th>主要代价</th></tr></thead><tbody><tr><td>视觉编码批</td><td>图像分辨率 → patch 数</td><td>分辨率分布</td><td>padding 浪费、视觉池排队</td></tr><tr><td>Q-Former 批</td><td>查询数固定</td><td>几乎为零</td><td>特征缓冲带宽</td></tr><tr><td>语言解码批</td><td>查询数 + 文本长度</td><td>文本长度、生成长度</td><td>前缀 KV 显存、解码步负载不均</td></tr></tbody></table>\n<p>具体例子：单图加短文本的请求形态下，文本长度分布很短，分桶后批内方差小，连续批处理能把解码步的 GPU 利用率维持住；一旦混入长文本请求，若不按长度分桶，短请求会在长请求的每一步解码中空转，吞吐下降而尾延迟上升。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-28\">二十八 · chunked prefill 与软前缀的拼接时机</h3>\n<p>chunked prefill 的作用是把长 prefill 切成若干块，与解码步交错执行，避免一个长 prefill 阻塞整个批。对 BLIP-2 而言，prefill 的对象是「软前缀 + 文本 token」拼接后的序列。软前缀来自 Q-Former，长度固定但数值上是连续向量而非离散 token，因此切块时前缀块与文本块的边界必须与 KV 写入顺序一致：前缀 KV 先写入并可在同图多轮请求间复用，文本块再逐块追加。</p>\n<p>这带来一个调度上的机会：同一图像的多轮请求可以跳过前缀 prefill，直接复用已写入的前缀 KV，只对新增文本做 prefill。首轮冷前缀请求的时延包含视觉编码 + Q-Former + 前缀 prefill，后续热前缀请求只剩文本 prefill 与解码。SLO 必须把这两类请求分开设定目标，否则冷请求会把热请求的尾延迟统计拉偏。</p>\n<div class=\"formula\">$$T_{\\text{prefill}}^{\\text{cold}} = T_{\\text{vis}} + T_{\\text{qformer}} + T_{\\text{prefix}},\\quad T_{\\text{prefill}}^{\\text{hot}} = T_{\\text{text}}$$</div>\n<p>代价落在显存与带宽上：前缀 KV 复用要求缓存按图像身份索引，缓存命中率决定显存中前缀 KV 的驻留比例；若命中率低，前缀 KV 反复写入会占用带宽并挤占解码批的显存预算。工程判断是给前缀 KV 设独立配额，按图像热度做淘汰，而不是与解码 KV 混在同一池里竞争。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-29\">二十九 · 优先级、抢占与尾延迟</h3>\n<p>多模态请求的优先级往往不由文本长度决定，而由业务语义决定：交互式请求要低首 token 延迟，批处理请求要高吞吐。BLIP-2 的分池结构让优先级可以分池实施——视觉池按队列深度设优先级，语言池按剩余生成长度做抢占。抢占的粒度是序列 slot：低优先级序列被换出时，其前缀 KV 可保留（前缀与已生成 token 的 KV 是确定的），只释放解码中的中间状态，换回时从前缀 KV 继续。</p>\n<p>尾延迟的来源在分池下有两个：视觉队列积压与解码批的长尾。前者用并发上限加排队超时处理，超时请求在前缀拼接前降级返回；后者用分桶加 chunked prefill 压低单步最长执行时间。具体例子：当视觉池积压而语言池空闲时，尾延迟由视觉侧排队主导，此时扩容语言池无效，必须单独监控视觉队列深度并对其扩缩容。反过来，语言池的长文本请求会造成解码步长尾，需要按生成长度设上限或把长请求路由到独立批。</p>\n<ul>\n<li>监控项：视觉队列深度、前缀长度分布（应恒定）、文本长度分布、解码步 p99、前缀 KV 命中率。</li>\n<li>降级路径：视觉超时 → 降分辨率或返回缓存前缀；解码超时 → 截断生成并按 SLO 返回。</li>\n<li>扩缩容解耦：视觉池按图像到达率扩，语言池按活跃序列数与生成长度扩，两者不共享并发上限。</li>\n</ul>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-30\">三十 · 分离式预填/解码在 BLIP-2 路径上的落点</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）把 prefill 与 decode 放到不同实例，中间通过 KV 传输衔接。BLIP-2 的路径天然适合这种切分：Q-Former 输出的软前缀与文本拼接后的 prefill 可以在预填实例完成，前缀 KV 与文本 KV 一起传给解码实例；解码实例只做逐 token 生成，显存以 KV 为主、计算以解码 kernel 为主。由于前缀定长，KV 传输的尺寸可预测，传输带宽预算可以按「并发数 × 前缀 KV + 文本 KV」静态估算。</p>\n<p>代价是传输延迟与实例间的负载匹配：预填实例的吞吐由视觉编码与 Q-Former 决定，解码实例的吞吐由解码步与 KV 带宽决定，两者扩缩容不同步时，KV 传输队列会成为新的排队点。工程上要把前缀 KV 的复用与分离式部署结合：热前缀请求直接在解码实例命中缓存，冷前缀请求才走预填实例，从而把跨实例传输量压到只含新增文本 KV。</p>\n<div class=\"formula\">$$B_{\\text{kv}} = N_{\\text{active}} \\times \\big(s_{\\text{prefix}} + s_{\\text{text}}\\big) \\times b_{\\text{elem}}$$</div>\n<p>具体例子：查询数固定使 $s_{\\text{prefix}}$ 为常数，提高图像分辨率只增加视觉池计算与特征缓冲带宽，不增加 $B_{\\text{kv}}$；因此高分辨率请求的成本应记在视觉池的扩容预算上，而不是解码实例的 KV 预算上。这一条是 BLIP-2 调度机制最直接的工程推论：分辨率与语言侧容量解耦，容量规划必须按池分别做，混算会同时高估解码显存与低估视觉排队。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-31\">三十一 · 分池调度下的尾延迟边界与失效条件</h3>\n<p>把 BLIP-2 的推理路径拆成视觉池、桥接池与语言池之后，调度器面对的不再是单一序列长度分布，而是两条互相耦合却节奏不同的队列。视觉编码器按图像批前向，单批耗时由分辨率与 patch 数决定，与文本长度无关；语言池按前缀加文本的序列长度分桶做连续批处理，解码步进受 KV 带宽约束。二者之间只有一条窄通道：定长查询表示经投影成为软前缀。这条通道的宽度是固定的——查询数决定了前缀长度 <span>L<sub>p</sub></span>，于是语言侧每请求的 KV 占用与首 token 时延可以写成 <span>KV ∝ L<sub>p</sub> + L<sub>gen</sub></span>，而视觉侧计算量随分辨率单调上升却不会反馈到 <span>L<sub>p</sub></span>。调度上的直接后果是：提高分辨率只把压力堆到视觉池，语言池的批组成不变，两池的扩缩容信号必须分开采集，否则会出现视觉队列积压而语言池空转的错配。</p>\n<p>连续批处理在这个结构里的收益与风险都来自前缀定长。由于同一图像的多轮请求共享同一段软前缀 KV，热前缀请求进入语言池时可以跳过前缀计算，直接参与解码批，批内序列长度差异仅来自已生成 token 数，分桶效率高。但冷前缀请求必须等视觉池产出查询表示后才能拼批，其首 token 时延等于视觉排队时间加视觉前向时间加桥接前向时间加语言侧首步时间。设视觉池到达率为 <span>λ<sub>v</sub></span>、单批服务率为 <span>μ<sub>v</sub></span>，队列深度近似随 <span>λ<sub>v</sub>/μ<sub>v</sub></span> 上升而发散，尾延迟由视觉侧主导而非解码侧。chunked prefill 在这里的作用有限：它切分的是语言侧长前缀的预填，而 BLIP-2 的前缀本身是定长的，真正需要切分的是视觉编码器的大分辨率前向——把一张高分辨率图拆成多个 patch 子批送入，用吞吐换单请求时延，代价是桥接模块要跨子批聚合，跨模态注意力的调用次数增加。</p>\n<p>优先级与抢占的设计要区分冷热前缀。热前缀请求的 KV 已在显存中，抢占它意味着丢弃可复用状态，重算代价是整段前缀的重新投影与前向；冷前缀请求尚未占用语言侧 KV，抢占代价低。因此合理的策略是：视觉池按分辨率与队列深度设置并发上限，超时请求在前缀拼接前降级返回；语言池对热前缀请求给高优先级并保护其 KV 块不被换出，对冷前缀请求允许排队。分离式预填/解码在这里的映射是视觉编码与语言解码物理分池，预填阶段被前移到视觉池与桥接池完成，解码池只处理软前缀加已生成 token，两池之间的传输量是定长查询表示，带宽需求远小于逐 token 的 KV 传输。代价是跨池同步点增加：每次请求都要在桥接池出口做一次拼接与路由，池间网络时延直接进入首 token 关键路径。</p>\n<p>失效条件集中在三处。其一，查询数上限即压缩上限，高分辨率输入只增加视觉侧计算而不增加语言侧信息量，调度器若按分辨率提升优先级，等于把算力投向不改变前缀长度的路径，尾延迟上升而质量不变。其二，视觉池与语言池扩缩容不同步时，尾延迟由视觉排队主导，监控必须单独跟踪视觉队列深度、前缀长度分布与解码尾延迟三条曲线，任何一条缺失都会让容量判断失真。其三，材料未给出量化方案与吞吐时延实测数字，桥接模块与投影层在低比特下的数值稳定性、两池精度分配均无可核验结论，容量规划只能落在“前缀定长、分池部署、热前缀复用”的机制层面，不能引用具体指标做 SLO 承诺。工程判断是：把 SLO 拆成冷前缀与热前缀两档目标，视觉池按队列深度而非按分辨率做准入控制，语言池按前缀长度分桶并保护热前缀 KV，三池各自独立扩缩容，池间只传定长表示。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-32\">三十二 · 分池拓扑：三组件各自的并行维度</h3>\n<p>BLIP-2 的推理路径天然是三个异构子系统：冻结图像编码器、Q-Former 桥接、冻结语言模型。并行切分不能按“一个模型一种切法”套用，而要按各池的瓶颈维度分别选轴。视觉编码器侧，计算量与图像批大小成正比、与分辨率平方相关，单卡显存通常足以容纳一个 ViT 级编码器，因此首选数据并行（DP）：每张卡持完整编码器副本，按图像批切分，All-Reduce 只发生在需要同步的极少参数上——编码器冻结，梯度不存在，DP 组内几乎无集合通信，代价仅是输入分发。Q-Former 参数量远小于两侧，查询数固定，跨模态注意力在视觉特征序列上做，序列长度由 patch 数决定；它适合与视觉池同卡或紧随其后，用张量并行（TP）切查询维度收益有限，因为查询数本身很小，切分后每卡计算量不足以摊薄通信。语言模型池才是 TP/EP/PP 的主战场：TP 切隐层与注意力头，每层两次 All-Reduce；EP 切 MoE 专家，每层一次 All-to-All；PP 切层段，只在段边界传激活。DP 在语言池用于扩副本数，与 TP/PP 正交组合。</p>\n<p>一个具体例子：GB200 NVL72 单机架内 72 个 GPU 通过 NVLink 5 与 NVSwitch 全互联，语言池取 TP=8、PP=4、DP=2 的 64 卡拓扑，视觉池单独占 4 卡做 DP，Q-Former 与投影层寄居视觉池。视觉池与语言池之间只传定长查询表示，传输量是 <span>查询数 × 隐层维度 × 精度字节</span>，与图像分辨率无关——这正是分池拓扑的通信红利：跨池链路只承载压缩后的前缀，不承载逐 patch 特征。</p>\n<p>代价落在哪：TP 组内每层 All-Reduce 的通信量与隐层维度、批内 token 数成正比，TP 越大单卡计算越少但通信占比越高；PP 引入流水线气泡，段数越多气泡占比越大，解码阶段每 token 都要走一遍段间传递，尾延迟被最慢段决定；EP 的 All-to-All 在解码时每 token 都要做专家路由，是 MoE 语言池的固定开销。视觉池 DP 几乎零通信，但它的扩缩容与语言池不同步时，跨池队列就成为尾延迟来源。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-33\">三十三 · 集合通信的三种形态与何时压垮链路</h3>\n<p>语言池的集合通信可归为三类。All-Reduce（TP 每层两次）：环状或树状实现，通信量约 <span>2×(N−1)/N×M</span>，M 为该层参与归约的激活字节数，N 为 TP 组大小；当 M 随批内 token 数增长时，通信时间线性上升。All-Gather/Reduce-Scatter（ZeRO 式分片或序列并行）：把激活或参数按 token/通道切分，通信量与切分维度上的数据量同阶。All-to-All（EP）：每个 token 被路由到若干专家所在卡，通信量约 <span>token 数 × 路由专家数 × 隐层字节</span>，且呈非对称、非均匀分布——热点专家造成链路倾斜。</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx \\frac{M}{B_{\\text{link}}\\cdot \\eta} + L_{\\text{lat}},\\qquad \\text{TP 扩展效率} \\approx \\frac{T_{\\text{comp}}}{T_{\\text{comp}} + T_{\\text{comm}}}$$</div>\n<p>其中 B_link 为单卡有效链路带宽，η 为集合通信效率（受算法、消息大小、并发流影响），L_lat 为固定启动延迟。判断通信是否成为瓶颈的工程判据是：单层计算时间 T_comp 与 T_comm 的比值。当批内 token 数很小（解码阶段每步仅 1 个 token 时尤其明显），T_comp 被压到极低，T_comm 中的 L_lat 项主导，TP 扩展效率急剧下降——这就是解码阶段 TP 度数不宜过大的根本原因。反之在预填阶段，批内 token 数大，M 大，T_comm 随 M 线性增长但 T_comp 增长更快（注意力与 MLP 对 token 数近似线性），TP 仍能摊薄。</p>\n<p>具体例子：语言池 TP=8 时，每层两次 All-Reduce，若隐层 8192、批内 4096 token、FP8 精度，单次归约消息量在数十 MB 量级，NVLink 5 单卡带宽足以在微秒级完成，但启动延迟与多流竞争使实际有效带宽打折；若同一拓扑跑在解码阶段、批内仅数百 token，消息量缩小两个数量级，L_lat 占比上升，TP=8 的收益被通信吃掉。工程判断：预填用大 TP、解码用小 TP 或改用 PP/DP 扩副本，是分离式预填/解码拓扑的直接动机。</p>\n<p>跨池通信则是另一回事：视觉池到语言池只传前缀，量小、频率低（每请求一次），不构成带宽瓶颈，但构成同步点——前缀未就绪，语言池的批就凑不齐，调度器被迫等待，表现为队列积压而非链路饱和。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽的边界</h3>\n<p>NVLink 5 与 NVSwitch 把单机架内 GPU 做成全互联域，集合通信不再经过 PCIe 或主机网络，All-Reduce 与 All-to-All 可在域内以高带宽、低延迟完成。这改变了切分策略的可行域：TP 组应尽量落在同一 NVLink 域内，因为 TP 是每层同步、延迟敏感的集合通信；跨域 TP 会把每层归约拖到域间链路上，T_comm 中的 B_link 骤降，扩展效率崩塌。PP 的段间传递频率低（每 micro-batch 一次），对带宽不敏感但对延迟敏感，段边界可跨域但需控制段数。DP 的梯度/参数同步在推理时几乎不存在，副本可跨域放置。EP 的 All-to-All 频率高、分布不均，必须域内。</p>\n<p>代价的量化视角：域内带宽提升并不自动转化为端到端吞吐，因为集合通信的实际有效带宽受消息大小与并发流数制约。小消息走 NVSwitch 的固定延迟占主导，大消息才逼近峰值带宽。因此“把 TP 从 4 提到 8”在预填阶段可能提升吞吐，在解码阶段可能因消息变小而净亏。工程上应把 TP 度数、批内 token 数与精度字节一起作为联合调参对象，而不是单独调 TP。</p>\n<p>具体例子：NVL72 机架内语言池做 TP=8 时，All-Reduce 全程走 NVSwitch，无需主机介入；若把同一 TP 组拆到两个机架，每层归约跨机架链路，单层通信时间上升一个量级，解码尾延迟直接失控。结论落在拓扑约束上：TP 组必须域内闭合，PP 段可跨域，EP 组必须域内且需按专家热度做负载均衡。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-35\">三十五 · NIXL 传输：跨池与跨节点的数据面</h3>\n<p>分池部署意味着视觉特征、查询表示、KV 前缀要在池间搬运。NIXL 提供的是点对点、低开销的数据面传输抽象，把显存到显存的搬运从主机 CPU 路径上卸下来，支持跨节点、跨池的直接传输。对 BLIP-2 推理路径而言，真正需要 NIXL 的是三类数据：视觉池写出的查询表示（定长、小）、同图多轮请求复用的前缀 KV（较大、可跨请求复用）、以及分离式预填/解码场景下预填池向解码池传递的 KV。</p>\n<p>传输代价的判断依据是“搬运量 × 频率”与“是否阻塞计算”。查询表示每请求一次、量小，NIXL 传输延迟可被视觉池的批处理掩盖；前缀 KV 复用场景下，搬运量与查询数、隐层维度、层数成正比，若同图多轮请求密集，KV 搬运会成为跨池带宽的主要占用者，此时应优先让复用请求落到持有该前缀 KV 的同一解码副本上（亲和调度），把传输变成命中而非搬运。分离式预填/解码下，KV 从预填池传到解码池是每请求必发生的一次大传输，其带宽需求与请求速率、上下文长度成正比，是容量规划中必须单列的一项。</p>\n<p>具体例子：同一图像被多轮追问时，首轮冷前缀需在解码池建立 KV，后续轮次若调度到同一副本则零传输；若调度器按负载均衡把请求打散到不同副本，每轮都要搬一次前缀 KV，跨池带宽被重复占用，尾延迟上升。工程判断：前缀 KV 的复用必须与调度亲和性绑定，否则 NIXL 传输从“偶发”变成“每请求”，分池的通信红利被抵消。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-36\">三十六 · 通信成为瓶颈的判据与切分决策</h3>\n<p>把前述机制收束成可操作的判据。第一，看阶段：预填阶段 token 多、T_comp 大，TP 扩展效率高，通信不易成为瓶颈；解码阶段 token 少、T_comp 小，L_lat 主导，TP 度数应压低，改用 DP 扩副本或 PP 拉长流水。第二，看消息大小：集合通信有效带宽随消息增大而上升，小消息阶段应减少集合通信次数而非追求更大 TP。第三，看域边界：TP 与 EP 组必须落在 NVLink 域内，跨域即瓶颈；PP 段可跨域但段数受气泡约束。第四，看跨池队列：视觉池与语言池扩缩容不同步时，瓶颈不在链路而在排队，监控对象是队列深度与前缀就绪时间，不是带宽利用率。</p>\n<table class=\"mini\"><thead><tr><th>切分轴</th><th>通信形态</th><th>频率</th><th>瓶颈判据</th><th>适用池</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>每层每步</td><td>解码阶段消息小、L_lat 主导</td><td>语言池预填</td></tr><tr><td>EP</td><td>All-to-All</td><td>每层每 token</td><td>专家热度倾斜、域内带宽</td><td>MoE 语言池</td></tr><tr><td>PP</td><td>段间激活传递</td><td>每 micro-batch</td><td>流水线气泡、最慢段</td><td>语言池跨域</td></tr><tr><td>DP</td><td>几乎无集合通信</td><td>—</td><td>副本间负载均衡</td><td>视觉池、语言池解码</td></tr><tr><td>跨池</td><td>NIXL 点对点</td><td>每请求</td><td>前缀 KV 复用命中率</td><td>视觉→语言、预填→解码</td></tr></tbody></table>\n<p>具体例子：一个以单图短文本为主的负载，视觉池 4 卡 DP、语言池 TP=4 预填 + DP=8 解码副本，跨池只传定长查询表示，NIXL 传输被前缀 KV 亲和调度吸收；当并发上升、视觉编码队列积压时，端到端尾延迟由视觉池排队主导，此时增加语言池 TP 度数毫无收益，正确动作是扩视觉池副本或提前做前缀缓存。这就是“通信什么时候成为瓶颈”的工程答案：不是看链路利用率，而是看当前阶段的最小 T_comp 单元是否已被 T_comm 或排队时间盖过。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-37\">三十七 · 分池并行下的通信边界：切分维度与瓶颈判据</h3>\n<p>BLIP-2 推理路径的可分池特性决定了并行拓扑不是单一维度的选择：视觉编码器按图像批做数据并行即可，其参数冻结、无跨卡激活依赖；真正需要切分的是语言模型池，而 Q-Former 与投影层因参数量极小，通常整卡驻留、不参与切分。于是 TP 只作用于语言模型隐层维度，EP 仅在语言模型为 MoE 结构时才有意义，PP 用于把前缀拼接后的长序列解码按层切段以降低单卡显存，DP 则复制语言模型副本承接不同桶的请求。关键判据是每 token 每层的通信量与计算量之比：当批内 token 数因前缀定长而偏小、解码处于 memory-bound 区间时，TP 的 All-Reduce 时延无法被计算掩盖，TP 度数的收益迅速衰减。</p>\n<div class=\"formula\">$$\\eta=\\frac{T_{\\text{comm}}}{T_{\\text{comm}}+T_{\\text{comp}}},\\quad T_{\\text{comm}}\\approx\\frac{2(N-1)}{N}\\cdot\\frac{S\\cdot H\\cdot b}{B_{\\text{link}}}$$</div>\n<p>式中 N 为 TP 度数，S 为序列长度（含定长软前缀），H 为隐层维度，b 为字节宽度，B_link 为链路有效带宽。前缀定长意味着 S 中有一部分不随图像分辨率增长，因此提高分辨率只加重视觉池负担，语言池的 All-Reduce 消息尺寸不变——这正是分池部署在通信上的直接好处：视觉侧的高分辨率计算不会把跨卡集合通信拖入解码关键路径。反过来，若把视觉编码器与语言模型强行同池共卡，视觉前向的激活峰值会挤占解码 KV cache，迫使 PP 切分加深，PP 的流水气泡在短文本、小批解码下更难填满，气泡占比上升直接表现为尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>作用对象</th><th>通信原语</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>语言模型隐层</td><td>All-Reduce（每层两次）</td><td>批内 token 少、解码 memory-bound 时通信不可掩盖</td></tr><tr><td>EP</td><td>MoE 专家</td><td>All-to-All</td><td>专家负载倾斜，令牌路由不均导致单卡排队</td></tr><tr><td>PP</td><td>解码层段</td><td>点对点激活传递</td><td>微批不足，流水气泡吞掉并行收益</td></tr><tr><td>DP</td><td>语言模型副本</td><td>无（仅前缀 KV 复用需跨副本取数）</td><td>同图多轮命中不同副本，前缀 KV 需经 NIXL 迁移</td></tr></tbody></table>\n<p>All-to-All 在 EP 下的代价与 TP 不同：它交换的是令牌而非激活分片，消息尺寸随批内 token 数线性增长，因此连续批处理把长短序列分桶后，EP 的通信量分布会随桶而剧烈波动，负载倾斜时单卡成为瓶颈。NIXL 在此承担的是跨池、跨副本的数据搬运——同图多轮请求若被调度到未持有该图前缀 KV 的语言模型副本，需经 NIXL 从前一副本拉取软前缀 KV，其传输量等于前缀长度乘 KV 头维度乘层数乘字节宽度，属于可避免的通信；调度器应做前缀亲和性路由，把同图请求粘在同一副本上，使热前缀命中本地显存而非跨节点搬运。NVLink 5 与 NVSwitch 决定单节点内 TP/EP 集合通信的上限，跨节点则退化为 RDMA 路径，此时 TP 度数应受限于节点内域，跨节点只做 DP 与前缀 KV 的按需迁移。工程判断落在监控上：分别跟踪视觉队列深度、语言池 All-Reduce 时延占比与前缀 KV 跨副本迁移字节数，三者中任一持续抬升即说明当前切分维度与请求形态失配，应优先调整分桶策略与副本亲和性，而非盲目加大 TP 度数。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-38\">三十八 · 精度塌陷：桥接模块是低比特下的第一道裂缝</h3>\n<p>BLIP-2 的推理路径上，真正参与前向的只有 Q-Former 与线性投影这一小段，两侧大模型冻结。这带来一个容易被误读的工程直觉：既然桥接模块参数量远小于两侧，量化它应该“便宜且安全”。实际相反——桥接模块承担的是跨模态对齐的全部语义负荷，视觉特征经跨模态注意力压成定长查询表示 <span class=\"formula\">$$\\mathbf{z}=\\mathrm{QFormer}(\\mathbf{V}),\\quad \\mathbf{h}=\\mathbf{W}\\mathbf{z}$$</span>，这一步把变长 patch 序列的信息浓缩到固定维度，任何数值扰动都会被后续语言模型当作“事实前缀”消费，而不是像普通隐层那样在深层残差中被稀释。精度塌陷的典型表现不是输出乱码，而是描述退化为模板化、属性错配（颜色、数量、空间关系）、以及同一图像多轮请求之间答案漂移。诊断上要把桥接模块单独拉出来做数值对照：同一批图像分别走 FP16 与目标低比特桥接，比较查询表示的余弦相似度分布与投影后前缀的范数偏移；若前缀范数整体收缩或注意力权重熵骤降，说明量化把跨模态注意力压平了。代价侧，桥接模块本身显存占用小，回滚到高精度几乎不增加显存，但会改变前缀数值分布，进而影响已缓存的视觉前缀 KV——回滚必须同时失效前缀缓存，否则热前缀与冷前缀混用会制造更隐蔽的错配。具体例子：同图多轮问答中首轮用低比特桥接写入前缀 KV，第二轮命中缓存却换了精度档位，语言模型看到的前缀与首轮不一致，答案在“图中有两只猫”与“图中有一只猫”之间抖动，而监控只看到时延正常。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-39\">三十九 · OOM 的三条来源与分池隔离</h3>\n<p>BLIP-2 把视觉编码器、桥接、语言模型分池部署，OOM 因此不再是单一进程的显存问题，而是三个池的配额错配。第一条来源是视觉池：图像分辨率提高只增加视觉编码器侧计算，不改变语言模型前缀长度，于是视觉池的激活显存随分辨率与图像批增大，而语言池的 KV 占用纹丝不动——扩容视觉池时若沿用语言池的批大小经验，会直接打爆视觉侧激活。第二条来源是语言池 KV：KV cache 只覆盖软前缀与已生成 token，前缀长度由查询数固定，因此单请求 KV 上限可预测，OOM 来自并发数乘以固定前缀长度加上生成 token 的增长，属于容量规划问题而非突发。第三条来源最隐蔽：前缀缓存复用。同图多轮请求复用前缀 KV 节省了重算，但缓存条目本身占显存，缓存命中率越高、驻留条目越多，语言池可用 KV 块越少，形成“越优化越容易 OOM”的反直觉回路。工程判断是给前缀缓存设独立配额并做 LRU 淘汰，而不是让它和活跃请求共享同一个显存池；同时视觉池与语言池的并发上限必须解耦设置，视觉池按分辨率分档限流，语言池按前缀长度分桶限流。定位手段是分别打点三个池的显存高水位与分配失败次数，任何一次分配失败都要记录当时的分辨率档、前缀缓存条目数与活跃批大小，否则 OOM 日志只剩一个没有上下文的栈。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-40\">四十 · 批抖动：视觉队列与解码队列的节拍不同步</h3>\n<p>批抖动的根源是两条流水线的服务时间分布形状不同。视觉编码器按图像批做前向，单批时间由分辨率与批大小决定，方差相对小；语言解码是逐 token 自回归，生成长度分布长尾，单请求占用解码槽的时间方差大。调度器按前缀长度与文本长度分桶做连续批处理，但分桶只对齐了“进入语言池时的序列形状”，没有对齐“离开视觉池的时刻”。当并发上升，视觉编码队列先积压，请求在前缀拼接前等待，此时语言池的批因为缺少新请求而变小，解码吞吐下降，形成视觉侧排队放大语言侧空转的耦合抖动。监控上要同时看两个指标：视觉队列深度的时间序列，以及语言池每步实际批大小与名义批大小的比值；后者持续低于某阈值而前者持续上升，就是典型的不同步信号。缓解机制是给视觉池设独立的并发上限与排队超时，并在前缀拼接前做一次“可拼接性”检查——若视觉结果到达时语言池当前批已接近解码尾声，宁可让该请求等下一个批窗口，也不要塞进一个即将关闭的批造成槽位浪费。代价是尾延迟被批窗口量化，首轮冷前缀请求的 P99 会比均值高出明显一截，因此 SLO 必须把冷前缀与热前缀分开设定，热前缀请求命中缓存后几乎不经过视觉队列，其尾延迟由语言池单独决定。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-41\">四十一 · 尾延迟：固定查询数掩盖不了长尾</h3>\n<p>固定查询数让语言模型侧序列长度与图像分辨率解耦，这常被误当作尾延迟已经被消除。实际被消除的只是“前缀长度随分辨率增长”这一项，尾延迟仍有三个独立来源。其一是视觉编码器侧：高分辨率图像在视觉池的单批时间更长，若与低分辨率图像混批，整批被最慢样本拖住，尾延迟由分辨率分布的上尾决定，而不是由查询数决定。其二是生成长度：语言模型自回归的 token 数分布长尾，KV 随生成增长，解码槽占用时间随之上尾，这与前缀定长无关。其三是缓存未命中：首轮冷前缀要完整走视觉编码加桥接前向，热前缀直接命中 KV，两者时延差一个数量级，混合流量下 P99 由冷前缀请求主导。诊断要把尾延迟按“分辨率档 × 冷热前缀 × 生成长度桶”三维切分，任何一维的上尾都可能单独撑起整体 P99；只按平均时延做容量规划会系统性低估所需并发。机制上可做的是分辨率分档混批约束（同批内分辨率跨度受限）与冷前缀请求的预留槽位，代价是牺牲一部分批填充率换取尾延迟可预测。具体例子：一个以单图短文本为主的负载，均值时延平稳，但 P99 在分辨率上尾与冷前缀叠加时出现尖峰，监控若只看均值会误判系统健康。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-42\">四十二 · 静默降级与回滚：降级必须可观测、可逆</h3>\n<p>BLIP-2 的推理路径允许在解码超时时按 SLO 降级返回，这条机制本身是尾延迟的最后一道闸，但它也是静默降级的温床。降级有三种形态：截断生成（返回不完整描述）、跳过桥接高精度档（用低比特前缀换取速度）、以及直接丢弃超时请求返回兜底文本。三者的共同问题是它们都表现为“成功返回”，监控若只统计错误码，会把降级率当作零。工程要求是把降级做成显式状态位并计入成功率分母之外的独立指标，同时记录降级发生时的队列深度、前缀冷热与生成长度，否则无法判断降级是容量不足还是单请求异常。回滚路径要覆盖三个层次：精度档回滚（桥接与投影回到高精度并失效前缀缓存）、调度参数回滚（恢复上一版并发上限与批窗口）、以及缓存策略回滚（关闭前缀复用或缩小缓存配额）。回滚的代价不对称——精度回滚几乎不增显存但会短暂降低缓存命中率，调度回滚会立刻改变批形状并可能引发一轮批抖动，缓存回滚则直接把热前缀请求推回视觉队列，尾延迟瞬时抬升。因此回滚要按“先精度、再缓存、最后调度”的顺序做，并在每一步之后观察视觉队列深度与冷热前缀比例是否回到基线，而不是一次性全量切回。定位静默降级的有效手段是对同一请求做影子重放：把降级请求以高精度档在旁路重算一遍，比较两者输出差异，差异率突增即说明降级已越过可接受边界，此时应触发精度回滚而非继续扩容。</p>\n\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要观测点</th><th>定位手段</th><th>回滚顺序</th></tr></thead><tbody><tr><td>精度塌陷</td><td>查询表示余弦相似度、前缀范数偏移</td><td>同图高低精度影子对照</td><td>精度档 + 失效前缀缓存</td></tr><tr><td>OOM</td><td>三池显存高水位、分配失败上下文</td><td>按分辨率档与缓存条目数切分</td><td>缓存配额 → 并发上限</td></tr><tr><td>批抖动</td><td>视觉队列深度、实际/名义批大小比</td><td>拼接时刻与批窗口对齐检查</td><td>调度参数</td></tr><tr><td>尾延迟</td><td>分辨率×冷热×长度三维 P99</td><td>上尾样本回溯</td><td>混批约束 → 预留槽位</td></tr><tr><td>静默降级</td><td>显式降级状态位与降级率</td><td>影子重放差异率</td><td>精度 → 缓存 → 调度</td></tr></tbody></table>\n\n<p>把降级状态位与影子重放差异率绑定成一条联动规则，是这套诊断体系里最值得固化的一步：差异率越过阈值即自动触发精度回滚并失效前缀缓存，而不是等人工比对日志；这条规则把“静默”变成“可观测的显式事件”，也让回滚从被动救火变成容量规划的一部分。</p>\n\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-43\">四十三 · 桥接模块的边界条件：查询数上限、队列积压与静默降级</h3>\n<p>BLIP-2 推理路径的失效往往不在两侧大模型，而在被当作“无损压缩器”的固定查询数。Q-Former 以固定数量查询向量做跨模态注意力，输出定长查询表示 <span>z</span>，投影为软前缀 <span>h=Wz</span>；语言模型侧前缀长度与图像分辨率解耦，提高分辨率只增加视觉编码器侧计算，不改变前缀长度与 KV 占用。代价是聚合能力受查询数上限约束：细粒度信息（小目标、密集文字、细纹理）在跨模态注意力中被平均掉，模型仍能流畅生成，但答案细节缺失——这是典型的静默降级，输出格式合法、延迟正常，指标却在无声塌陷。诊断手段是把查询表示当作可观测对象：对同一图像在不同分辨率下计算前缀向量的余弦相似度与范数分布，若高分辨率输入的前缀几乎不变，说明视觉侧新增计算未被桥接模块消费，应触发告警而非归因于语言模型。</p>\n<p>第二类失效是批抖动与尾延迟。视觉编码与语言解码分池部署、按前缀长度与文本长度分桶做连续批处理，两池扩缩容不同步时，视觉编码队列积压成为主要排队失败模式。设视觉池服务率为 <span>μ_v</span>、到达率为 <span>λ</span>、并发上限为 <span>C_v</span>，则队列深度近似 <span>L_q ≈ λ/(μ_v·C_v−λ)</span>（<span>λ&lt;μ_v·C_v</span> 时成立）；一旦 <span>λ</span> 逼近上限，<span>L_q</span> 非线性发散，尾延迟由视觉侧排队主导而非解码侧。监控必须把视觉队列深度、前缀长度分布与解码时延分开采集，按首轮冷前缀与同图多轮热前缀分别设 SLO：热前缀可复用 KV，冷前缀则要计入视觉编码全链路。</p>\n<p>第三类是精度塌陷与 OOM。桥接模块与投影层参数量远小于两侧大模型，常被优先降到低比特；但材料未给出量化方案与数值稳定性结论，低比特下投影层输出分布偏移会直接污染软前缀，表现为生成重复、答非所问，且不抛异常。工程判断是：把桥接模块输出范数与前缀 KV 占用纳入监控，前缀 KV 只覆盖软前缀与已生成 token，其占用随并发线性增长，是 OOM 的第一来源；回滚策略应把桥接模块与投影层精度档位、查询数配置做成可热切换的版本化参数，一旦前缀范数漂移或队列深度持续超阈，先回滚桥接侧精度而非两侧大模型。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位与回滚</th></tr></thead><tbody><tr><td>精度塌陷</td><td>前缀范数漂移、生成重复率上升</td><td>回滚桥接/投影精度档位</td></tr><tr><td>OOM</td><td>前缀 KV 占用随并发线性上升</td><td>降并发上限、缩短前缀复用窗口</td></tr><tr><td>批抖动/尾延迟</td><td>视觉队列深度发散</td><td>视觉池独立扩容、设排队超时降级</td></tr></tbody></table>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-44\">四十四 · 口径先行：BLIP-2 的基准表该长什么样</h3>\n<p>讨论 BLIP-2 的“快慢”之前，必须先钉死一张口径表，否则任何数字都不可读。这张表至少要有六列：模型规模（视觉编码器档位、语言模型档位、查询数）、硬件档位（单卡 SM100 还是 GB200 NVL72 机柜级）、batch 与并发形态（图像批大小、语言侧连续批处理的并发序列数）、指标定义（TTFT 是到第一个文本 token 还是到软前缀拼接入池、TPOT 是否含前缀复用命中）、显存口径（是否计入视觉特征缓冲与软前缀 KV）、功耗口径（整机还是单卡、是否含视觉池空转）。BLIP-2 的推理路径是冻结视觉编码器 → Q-Former 定长查询 → 线性投影 → 软前缀拼文本 token → 冻结语言模型自回归，三段分属不同池，任何单点指标都必须标注它落在哪一段上。工程上最容易被误读的是把“端到端吞吐”当成语言池吞吐：视觉池与语言池独立扩缩容，端到端吞吐由两者中较慢的一段决定，单独报语言池 tokens/s 会系统性高估系统能力。</p>\n<p>指标定义要落到公式层面才不留歧义。设单请求视觉编码耗时为 <span>T_vis</span>、Q-Former 与投影耗时为 <span>T_bridge</span>、语言侧首 token 耗时为 <span>T_prefill</span>、后续每 token 耗时为 <span>t_dec</span>、输出长度为 <span>L</span>，则端到端时延可写成：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{vis}} + T_{\\text{bridge}} + T_{\\text{prefill}} + (L-1)\\,t_{\\text{dec}} + T_{\\text{queue}}$$</div>\n<p>其中 <span>T_queue</span> 是视觉编码队列的排队时间，在并发上升时它先于其他项膨胀。TTFT 若定义为“首个文本 token 到达”，则应包含前三项与排队项；若定义为“软前缀就绪”，则不含 <span>T_prefill</span>。两种定义在同一系统上可以差出整个语言侧预填的时间，跨论文比较时必须对齐到同一种。TPOT 则要明确分母是“生成 token 数”还是“含前缀的序列长度”，后者会把定长前缀摊进分母，让 TPOT 看起来更好。</p>\n<p>具体例子：同一张高分辨率图，视觉编码器侧 patch 数翻倍，<span>T_vis</span> 近似线性上升，但查询数固定，<span>T_bridge</span> 与语言侧前缀长度不变，于是 <span>T_prefill</span> 与 KV 占用都不变。此时若只报语言侧 TTFT，会得出“分辨率无关”的错误结论；端到端口径下则能看到视觉池成为瓶颈。这就是 BLIP-2 口径表的第一个工程判断：分辨率只买视觉侧计算，不买语言侧序列长度。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-45\">四十五 · 硬件档位与 batch：三段池的批形态根本不同</h3>\n<p>BLIP-2 的三段在 Blackwell 上的批形态不可混为一谈。视觉编码器是典型的图像批：一批图像按 patch 序列做前向，批大小受视觉特征缓冲显存约束，SM100 上可用 tcgen05 与 TMEM 承接大矩阵乘，但视觉侧多为卷积或 ViT 类结构，收益取决于算子形态而非单纯精度。Q-Former 是固定查询数的跨模态注意力，查询数小、序列短，属于低算术强度的“小算子”，在 2-SM MMA 下难以吃满，往往受限于 kernel 启动与访存，而不是算力。语言模型侧则是连续批处理：按软前缀长度与文本长度分桶，前缀定长使分桶边界稳定，这是 BLIP-2 对调度器最友好的性质。</p>\n<p>批大小的选择要写成分段函数式的判断，而不是拍一个数。设视觉池单卡显存为 <span>M_vis</span>、单图视觉特征占用为 <span>m_feat</span>、语言池单卡 KV 预算为 <span>M_kv</span>、单序列前缀 KV 为 <span>k_pre</span>、每 token KV 为 <span>k_tok</span>、平均输出长度为 <span>\\(\\bar{L}\\)</span>，则两侧的批上限分别是：</p>\n<div class=\"formula\">$$B_{\\text{vis}} \\le \\frac{M_{\\text{vis}}}{m_{\\text{feat}}},\\qquad B_{\\text{lang}} \\le \\frac{M_{\\text{kv}}}{k_{\\text{pre}} + \\bar{L}\\,k_{\\text{tok}}}$$</div>\n<p>两个上限由不同资源决定：视觉侧吃特征缓冲，语言侧吃 KV。工程上常见错误是让两侧共用同一个并发上限，结果视觉池空闲而语言池排队，或反之。正确做法是分别设并发上限与排队超时，并让调度器按前缀长度分桶——前缀定长意味着 <span>k_pre</span> 对所有请求相同，分桶只需按文本长度切，桶内序列长度方差小，连续批处理的填充浪费低。</p>\n<p>具体例子：GB200 NVL72 机柜级部署下，视觉池可以按图像批横向扩到多卡，语言池按序列长度分桶做连续批处理；若把两者绑在同一批里同步推进，视觉侧的长尾图像会拖住整批语言解码，TPOT 抖动被放大。分离部署的代价是跨池传输软前缀（定长、体量小），换来的是两侧各自按瓶颈扩缩容。这里的系统代价是显存与带宽的取舍：视觉特征缓冲与语言 KV 各自独立预算，跨池传输占用 NVLink 5 带宽但量级远小于 KV 搬运。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-46\">四十六 · 并发与队列：尾延迟由视觉池排队主导</h3>\n<p>BLIP-2 的并发行为有一个明确的先后顺序：并发上升时视觉编码队列先积压，因为视觉侧单请求计算量大且批形态刚性，而语言侧靠连续批处理可以细粒度插入。设到达率为 <span>\\(\\lambda\\)</span>、视觉池服务率为 <span>\\(\\mu_vis\\)</span>、语言池服务率为 <span>\\(\\mu_lang\\)</span>，系统稳定条件要求两段都满足 <span>\\lambda < \\mu</span>；由于 <span>\\(\\mu_vis\\)</span> 通常远小于 <span>\\(\\mu_lang\\)</span>（单图视觉前向 vs 短文本解码），瓶颈几乎总在视觉侧。排队时延随利用率上升而非线性增长，端到端尾延迟由视觉队列深度直接决定。</p>\n<p>伪代码层面的调度判断可以写成：请求到达后先查同图前缀缓存，命中则跳过视觉池直接进语言池；未命中则入视觉队列，队列深度超过阈值即触发降级（降分辨率或直接超时返回）。这一分支把“冷前缀”与“热前缀”的时延目标分开：冷前缀请求的 TTFT 包含 <span>T_vis</span> 与排队，热前缀请求的 TTFT 只剩 <span>T_prefill</span>。SLO 若不区分两者，会把热前缀请求的预算浪费在冷前缀的排队上，或反过来对冷前缀承诺了做不到的 TTFT。</p>\n<p>具体例子：同一图像的多轮问答，首轮冷前缀要付视觉编码与 Q-Former 的全额代价，后续轮次复用软前缀 KV，语言侧只需处理新增文本 token。工程上应把前缀 KV 的缓存命中率作为一等监控指标，与视觉队列深度并列。系统代价方面，前缀缓存占用语言池 KV 预算，命中率越高越省视觉算力与 NVLink 传输，但缓存淘汰策略不当会让显存被冷门图像占满，反而压低可服务的并发序列数。功耗口径上，视觉池空转与语言池空转是两笔账，分离部署让空闲段可以单独降频或缩容，这是 BLIP-2 分池机制在容量规划上的直接收益。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-47\">四十七 · 数字怎么读：哪些提升不可比</h3>\n<p>BLIP-2 相关报告里最不可比的提升有三类。第一类是“冻结两侧只训桥接”带来的训练侧节省被误读为推理侧加速：桥接模块参数量小，推理时只多一次小前向，它省的是对齐的训练代价与部署时的模型副本数，不是单请求的算力。把“只训少量参数”当成“推理更快”是口径错位。第二类是查询数变化带来的“压缩率”提升：查询数从多降到少，语言侧前缀变短、KV 变小、TTFT 下降，但细粒度信息保留程度同时下降，这是精度-时延的交换，不是免费的加速。第三类是分辨率提升被报成“视觉侧吞吐提升”：分辨率只增加视觉侧计算，不改变语言侧序列长度，若基准表未标注分辨率档位，两组数字不可并列。</p>\n<p>可比的判断可以形式化为“同口径四要素”：同一硬件档位、同一 batch 与并发形态、同一指标定义、同一显存与功耗口径。缺一项即不可比。例如一组数字报语言池 tokens/s 而另一组报端到端请求/s，两者分母不同；一组 TTFT 含视觉编码而另一组不含，差值可达整个视觉前向的时间。工程上应要求报告方给出分段时延拆解（<span>T_vis</span>、<span>T_bridge</span>、<span>T_prefill</span>、<span>t_dec</span>），而不是只给一个端到端均值——均值会掩盖视觉队列的长尾。</p>\n<p>具体例子：两个部署都声称“TTFT 降低”，一个是通过提高前缀缓存命中率（热前缀占比上升），另一个是通过降低查询数（前缀变短）。前者不改变单请求冷路径的计算量，后者改变了信息容量；把两者放进同一张对比表就是口径污染。正确读法是分别标注缓存命中率与查询数，并把精度指标并列，否则“提升”无法归因。系统代价上，查询数下降省的是语言侧 KV 显存与 <span>T_prefill</span>，但视觉侧 <span>T_vis</span> 不变，端到端收益被视觉池瓶颈截断——这正是 BLIP-2 分池结构下最典型的收益上限。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-48\">四十八 · 容量规划的机制推断：只能落到结构，不能落到数字</h3>\n<p>材料未给出吞吐、时延与显存的实测数字，也未给出量化方案，因此容量规划只能依据机制推断，不能引用具体指标。可推断的结构性结论有三条。其一，语言侧 KV 占用与前缀长度解耦于分辨率：前缀定长意味着 <span>k_pre</span> 是常数，提高分辨率只抬高 <span>m_feat</span> 与 <span>T_vis</span>，语言池的并发上限 <span>B_lang</span> 不受影响。其二，视觉池与语言池的扩缩容比例由请求形态决定：单图短文本场景下视觉侧是瓶颈，应给视觉池更多副本；多轮同图场景下前缀命中率高，语言池的 KV 预算与解码吞吐成为约束。其三，桥接模块与投影层可优先低比特，视觉编码器与语言模型按数值敏感度分别定精度——但材料未给出低比特下桥接模块的数值稳定性结论，这一步只能作为待验证的工程假设，不能写成已确认的收益。</p>\n<p>容量规划的伪代码思路是按段设上限并联合校验：给定目标并发 <span>N</span> 与目标端到端 SLO，先由视觉池服务率反解所需副本数，再由语言池 KV 预算反解可承载的序列数，两者取小者作为系统可承诺并发。若视觉侧副本数受机柜功耗上限约束，则需在“加视觉副本”与“降分辨率/降查询数”之间做取舍，后者改变精度而前者只改变成本。这一判断必须写进容量表，否则扩容决策会默认“加机器就能提并发”，忽略视觉池的功耗与显存刚性。</p>\n<p>具体例子：GB300 NVL72 机柜内，视觉池按图像批扩到多卡后，跨池软前缀传输走 NVLink 5，带宽开销小但延迟不可忽略；若把 Q-Former 与投影并入视觉池，可省一次跨池传输，代价是桥接模块与视觉编码器绑定扩缩容，失去独立量化与独立扩容的灵活性。这是 BLIP-2 分池机制在容量规划上的核心权衡：解耦换弹性，绑定换时延。最终落在工程判断上——基准表里每一个数字都必须标注它属于哪一段池、哪一种前缀状态（冷/热）、哪一档分辨率与查询数，缺一项就退回机制层面讨论，不引用数值。</p>\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-49\">四十九 · 迁移到别的模型：冻结假设先要成立</h3>\n<p>BLIP-2 的推理方案有一条隐含前提：两侧大模型都是冻结的，桥接模块是唯一被训练的参数。迁到别的模型时，第一个要检查的不是 Q-Former 结构，而是这条前提是否还成立。如果目标系统里语言模型需要持续微调、或者视觉编码器要与下游任务联合训练，那么“分池部署、分别量化、分别扩缩容”的收益会被训练侧的耦合吃掉：每次语言模型更新都要重新校准软前缀的语义分布，桥接模块的投影矩阵随之漂移，前缀 KV 的复用价值下降。判断标准很直接——若两侧模型的更新频率高于桥接模块的重训周期，这套解耦部署就不划算，应退回端到端联合部署。</p>\n<p>第二个迁移点是查询数与隐层维度的匹配。Q-Former 输出定长查询表示 <span>z</span>，经 <span>h = Wz</span> 映射到语言模型隐层维度。换一个隐层更宽或更窄的语言模型，投影层要重训，而查询数决定了前缀长度：前缀长度乘以隐层维度就是软前缀占用的 KV 显存。迁移时若沿用原查询数而语言模型隐层翻倍，前缀 KV 显存同比上升，容量规划必须重算。反过来，隐层变窄时固定查询数可能超出语言模型对前缀长度的有效注意力范围，前缀过长会稀释文本 token 的注意力权重。</p>\n<div class=\"formula\">$$M_{\\text{prefix}} = 2 \\cdot L_q \\cdot d_{\\text{LM}} \\cdot b \\cdot s$$</div>\n<p>其中 <span>L_q</span> 为查询数，<span>d_LM</span> 为语言模型隐层维度，<span>b</span> 为批内序列数，<span>s</span> 为 KV 精度字节数。这个式子说明迁移时前缀显存由查询数与隐层维度共同决定，不能只按查询数估算。工程上迁移到新语言模型的第一步应是锁定 <span>L_q</span> 与 <span>d_LM</span> 的乘积预算，再决定是否重训桥接。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-50\">五十 · 迁到别的领域：视觉侧假设最脆弱</h3>\n<p>这套方案对“图像切 patch 后由冻结编码器输出逐 patch 特征”的依赖，在跨领域迁移时最先断裂。视频输入不是单帧 patch 序列，而是带时间维的张量；若把每帧独立送视觉编码器再用 Q-Former 聚合，查询数固定意味着时间信息被压进同一组定长向量，帧间细粒度运动线索丢失。此时前缀长度仍与分辨率解耦，但语言模型侧看到的是被时间平均过的表示，对时序敏感的任务（动作识别、时序定位）不适用。正确做法是把查询向量按时间段分组，让前缀长度随时长线性增长，代价是 KV 显存随时长上升，容量规划从“定长前缀”变成“随时长线性”的模型。</p>\n<p>文档与表格类输入的问题不同：它们的信息密度集中在局部文本区域，固定查询数做全局跨模态注意力会把注意力预算摊薄到空白区域。迁移到这类领域时，桥接模块的聚合方式需要从均匀查询改为区域感知查询，或者在上游先做区域裁剪再送入视觉编码器。这不是改查询数能解决的，而是聚合机制本身要换。音频、点云同理：它们的“patch”语义与图像不同，跨模态注意力的归纳偏置需要重新设计，冻结编码器加轻量桥接的范式可以保留，但桥接模块不再是原样的 Q-Former。</p>\n<p>代价层面，跨领域迁移的隐性成本在视觉编码器池。视频场景下视觉侧计算随时长与帧率线性增长，而语言侧前缀定长，两侧扩缩容比例失衡，视觉编码队列积压会比单图场景更早出现。监控必须把视觉池的队列深度与单请求帧数分布绑定，而不是只看请求数。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-51\">五十一 · 哪里不适用：细粒度与长尾是硬边界</h3>\n<p>固定查询数是这套方案最硬的边界。查询数上限决定桥接模块能保留的细粒度信息量，提高图像分辨率只增加视觉编码器侧计算，不改变语言模型侧前缀长度，因此高分辨率输入不会自动提升语言模型可获得的信息量。对需要读取小字、计数密集目标、定位微小缺陷的任务，这条边界直接表现为准确率天花板，且无法通过加分辨率突破。判断规则：若任务的关键信息占图像面积比例低于查询向量可分辨的粒度，这套方案不适用，应改用保留更多视觉 token 的路径或区域裁剪加多轮查询。</p>\n<p>第二个不适用场景是超长文本与多图交错输入。前缀定长在单图短文本下是优势，但在多图请求里每张图都贡献一段定长前缀，前缀总长随图数线性增长，KV 显存与首 token 延迟同步上升；若再把长文档拼在其后，序列长度分桶会退化为长序列桶主导，短请求被拖累。此时分池部署仍有效，但“前缀定长即容量可控”的推断失效，容量规划要按图数与文本长度的联合分布做，而不是按单图前缀长度。</p>\n<p>第三个边界是数值精度。材料未给出量化方案与低比特下桥接模块的数值稳定性结论，因此迁移到 NVFP4/FP8 推理栈时，桥接模块与投影层能否低比特、视觉编码器与语言模型如何分配精度，只能按敏感度实验逐层定，不能照搬两侧大模型的量化配方。桥接模块参数量小但对齐精度要求高，低比特误差会直接体现在软前缀语义偏移上，这是迁移时最需要单独验证的一层。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-52\">五十二 · 规模上限：前缀复用率决定经济性</h3>\n<p>这套方案的经济性来自前缀 KV 在同图多轮请求间的复用。规模上限不在单请求延迟，而在复用率：当请求以单图单轮为主时，每次都要付冷前缀的视觉编码与前缀填充成本，视觉池成为吞吐瓶颈；当请求以同图多轮为主时，热前缀命中使语言池成为瓶颈，视觉池可缩容。容量规划应按冷热前缀比例分配两池资源，而不是按平均请求数。判断阈值：若热前缀命中率低到视觉编码成本无法被摊薄，分池部署的调度开销会超过收益，此时合并部署或在前端做图像去重缓存更划算。</p>\n<div class=\"formula\">$$T_{\\text{req}} \\approx T_{\\text{vis}} + T_{\\text{prefill}}(L_q) + T_{\\text{decode}}(n),\\quad T_{\\text{req}}^{\\text{hot}} \\approx T_{\\text{prefill}}(L_q) + T_{\\text{decode}}(n)$$</div>\n<p>冷热两条路径的差值就是视觉编码成本，复用率把这项成本从每次请求摊到多次请求上。规模上升时，视觉池的并发上限与排队超时决定尾延迟；语言池按前缀长度与文本长度分桶做连续批处理，桶的划分要随查询数与图数变化重调，否则长短序列互相拖累。规模上限的另一个约束是桥接模块本身：它虽小，但每个请求都要前向一次，查询数增加会线性抬高这部分计算，在极高并发下桥接池也会成为独立瓶颈，需要与两侧池分开监控。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-53\">五十三 · 工程判断：迁移前先做三项核对</h3>\n<p>迁移这套推理方案前，先核对三件事，任何一项不满足就不应照搬。第一，两侧模型是否真的保持冻结且更新频率低于桥接重训周期；第二，目标任务的关键信息粒度是否落在固定查询数可保留的范围内；第三，请求形态是否以同图多轮为主、热前缀命中率是否足以摊薄视觉编码成本。三项都满足时，分池部署、前缀定长、KV 只覆盖软前缀与已生成 token 的机制可以直接沿用，量化与调度按新模型的敏感度重定即可。</p>\n<ul>\n<li>核对冻结前提：两侧更新频繁则放弃解耦部署，退回联合部署。</li>\n<li>核对信息粒度：细粒度任务改用区域裁剪或多轮查询，不靠加分辨率。</li>\n<li>核对复用率：冷前缀为主时优先做图像去重缓存，再谈分池扩缩容。</li>\n</ul>\n<p>迁移时最容易被忽略的是分桶策略的连带修改。前缀长度由查询数固定，但多图请求使前缀总长随图数变化，文本长度分布也随领域改变，原分桶边界会失效。工程上应把分桶键从“前缀长度加文本长度”改为“图数、查询数与文本长度的联合分桶”，并在监控里同时跟踪视觉队列深度与前缀长度分布，否则尾延迟会被视觉侧排队主导而无法定位。规模上限最终落在复用率与桥接池并发这两项上，而不是落在某一层大模型的算力上。</p>\n\n<h3 id=\"paper-blip-2-bootstrapping-language-image-2023-sec-54\">五十四 · 迁移边界：定长前缀在什么条件下失效</h3>\n<p>这套方案的可迁移性由一条硬约束决定：语言模型侧的前缀长度恒等于查询数，与图像分辨率无关。迁移到新领域时，第一个要改的不是模型结构，而是判断该领域的有效信息是否落在查询数所能承载的容量之内。设单查询表示的等效信息带宽为 <span class=\"formula\">$$C_q$$</span>，则视觉侧进入语言模型的总信息量上界约为 <span class=\"formula\">$$N_q \\cdot C_q$$</span>，其中 <span class=\"formula\">$$N_q$$</span> 为固定查询数。文档理解、遥感、医学影像这类任务的有效判别信号常集中在少数像素级细节上，聚合时被跨模态注意力平均掉，表现为前缀“看起来有信息”但下游答不对。此时正确做法是提高视觉编码器侧分辨率并把细粒度特征旁路给下游（例如额外拼接触觉式局部 token），而不是加大查询数——查询数增加会线性抬升语言模型前缀 KV 占用与首 token 延迟，收益却受注意力聚合能力的次线性约束。</p>\n<p>第二个迁移代价出现在分池部署的假设上。原方案假定视觉编码与语言解码可以独立扩缩容，这在单图加短文本的请求形态下成立；迁到视频或多图输入时，视觉侧计算随帧数线性增长，而语言侧前缀仍是定长，两侧的负载比例被彻底改写。设视觉池单卡吞吐为 <span class=\"formula\">$$T_v$$</span>、语言池为 <span class=\"formula\">$$T_l$$</span>，当输入帧数 <span class=\"formula\">$$F$$</span> 满足 <span class=\"formula\">$$F \\cdot T_l &gt; T_v$$</span> 时，视觉编码队列成为尾延迟主导项，扩语言池毫无意义。工程判断是：迁移前先测该领域请求的视觉计算量与前缀长度的比值分布，若该比值方差大，就必须为视觉池单独设并发上限与排队超时，否则降级策略会在错误的一侧触发。</p>\n<p>第三个边界是精度分配。桥接模块参数量远小于两侧大模型，直觉上应优先低比特量化以省显存，但投影层是把查询表示映射到语言模型隐层维度的唯一通道，其数值误差会被后续自回归解码逐 token 放大。迁到 NVFP4/FP8 时，可迁移的是视觉编码器与语言模型的权重量化策略，不可直接迁移的是桥接模块的精度档位——材料未给出该模块在低比特下的数值稳定性结论，因此迁移到新领域时应把投影层保持在较高精度，仅对 Q-Former 内部注意力做低比特试验，并以任务指标而非困惑度作为验收标准。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>可直接沿用</th><th>必须重做</th></tr></thead><tbody><tr><td>前缀定长机制</td><td>序列长度与分辨率解耦</td><td>查询数按领域信息密度重估</td></tr><tr><td>分池部署</td><td>视觉/语言独立扩缩容</td><td>视觉池并发上限与超时阈值</td></tr><tr><td>KV 复用</td><td>同图多轮复用前缀 KV</td><td>视频场景的帧级前缀失效策略</td></tr><tr><td>量化</td><td>两侧大模型分别定精度</td><td>投影层精度档位需实测</td></tr></tbody></table>\n<p>规模上限落在查询数与前缀 KV 的乘积上：并发请求数上升时，前缀 KV 虽可跨同图多轮复用，但首轮冷前缀仍要占满一份显存，热前缀命中率决定实际容量。迁到高并发短文本场景，若同图复用率低，前缀 KV 的显存开销会与文本 KV 叠加，此时应把桥接模块单独成池并限制其批大小，用排队而非扩显存来吸收尖峰——这是该方案在规模上最容易被误判的一处。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">BLIP-2: Bootstrapping </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Language-Image Pr…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2023 · arXiv preprint</text></svg><figcaption><b>家谱</b> · BLIP-2: Bootstrapping L… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称，记为未给出</td></tr><tr><td>基线</td><td>材料未给出具体基线名称，记为未给出</td></tr><tr><td>主要结果</td><td>材料未给出可核验的数值结果，无法报告零样本检索、图像描述或视觉问答的具体指…</td></tr><tr><td>消融</td><td>材料未给出消融实验的具体配置与数值，无法列出查询数、阶段划分或投影方式的对…</td></tr><tr><td>局限</td><td>材料未给出失败模式与容量边界的量化结论；可确认的工程限制是视觉查询数为固定…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-blip-2-bootstrapping-language-image-2023 · 共 9 个片段</p>\n";break;}}})();
